window.VRAGEN_DATA=(window.VRAGEN_DATA||[]).concat([
 {id:'vbd-001',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-01T14:50:00',views:344,tags:['rentevast','rentevisie','advies'],beste:'vbd-001-a1',
  titel:'Hoe onderbouwen jullie de keuze voor een rentevaste periode?',
  body:`Een starter twijfelt tussen een korte en een lange rentevaste periode. Het renteverschil is beperkt, maar de klant heeft weinig buffer. Hoe onderbouwen jullie die keuze in het adviesrapport zonder een rentevoorspelling te doen?`,
  antwoorden:[
   {id:'vbd-001-a1',auteur:'u1',datum:'2025-10-01T22:04:00',rA:{u5:3,u8:3},rAdv:{u8:3},body:`Ik voorspel nooit de rente, maar koppel de keuze aan de risicobereidheid en draagkracht van de klant.
- Hoeveel kan de maandlast stijgen voordat het knelt? Reken een scenario met een hogere rente door.
- Hoe lang verwacht de klant in de woning te blijven en zijn er inkomenswijzigingen te verwachten?
- Weegt de zekerheid op tegen de meerkosten van de langere periode?
Bij een kleine buffer kom ik meestal uit bij een langere rentevaste periode. In het dossier leg ik het doorgerekende scenario, de risicobereidheid en de motivering van de keuze vast.`},
   {id:'vbd-001-a2',auteur:'u5',datum:'2025-10-02T17:33:00',rA:{u8:5},rAdv:{u8:5},body:`Goede aanpak. Ik laat de klant daarnaast in eigen woorden aangeven hoe hij een lastenstijging zou opvangen, dat maakt de risicobereidheid concreet. Leg ook vast dat de rente bij renteherziening hoger of lager kan uitvallen en dat de klant dat begrijpt. Zo is het advies achteraf goed te volgen.`}
  ]},
 {id:'vbd-002',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-04T19:25:00',views:44,tags:['rentemiddeling','boeterente','oversluiten'],beste:'vbd-002-a1',
  titel:'Rentemiddeling of oversluiten bij een lopende hoge rente?',
  body:`Een klant heeft nog een aantal jaren rentevast tegen een rente die ruim boven de huidige marktrente ligt. De geldverstrekker biedt rentemiddeling aan. Hoe vergelijken jullie rentemiddeling met volledig oversluiten naar een andere geldverstrekker?`,
  antwoorden:[
   {id:'vbd-002-a1',auteur:'u4',datum:'2025-10-05T14:55:00',rA:{u2:3},rAdv:{u2:3},body:`Ik zet beide routes naast elkaar op totale kosten over dezelfde periode.
- Rentemiddeling: de vergoeding wordt verwerkt in de nieuwe rente, vaak met een opslag. Vraag de berekening op bij de geldverstrekker.
- Oversluiten: vergoeding wegens vervroegde aflossing plus notaris-, taxatie- en advieskosten, tegenover de lagere rente elders.
- Kijk ook naar de fiscale behandeling: de vergoeding bij oversluiten kan onder voorwaarden aftrekbaar zijn, bij rentemiddeling loopt het via de rente.
Leg de vergelijking en de uitgangspunten vast in het dossier, inclusief de rentes per datum.`},
   {id:'vbd-002-a2',auteur:'u2',datum:'2025-10-06T06:51:00',rA:{u5:5},rAdv:{u5:5},body:`Let ook op het kasstroomeffect: bij oversluiten betaalt de klant de vergoeding vaak direct uit eigen middelen of meegefinancierd, bij rentemiddeling wordt het uitgesmeerd. Voor klanten met weinig liquiditeit kan dat de doorslag geven. Ik reken ook het break-evenpunt uit, zodat de klant ziet na hoeveel maanden de overstap zich terugverdient.`}
  ]},
 {id:'vbd-003',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-08T22:20:00',views:86,tags:['verhuisregeling','meeneemregeling','rente'],beste:'vbd-003-a1',
  titel:'Werkt de verhuisregeling ook bij een hogere hypotheek op de nieuwe woning?',
  body:`Een klant verkoopt zijn woning en koopt een duurdere woning. Hij wil zijn lage rente meenemen. Voor het extra bedrag is een aanvullende lening nodig. Hoe gaan geldverstrekkers daarmee om?`,
  antwoorden:[
   {id:'vbd-003-a1',auteur:'u1',datum:'2025-10-09T03:43:00',rA:{u2:4},rAdv:{u2:4},body:`Bij de meeste verhuisregelingen neem je het bestaande bedrag mee tegen de huidige rente en rentevaste periode, en sluit je het extra deel af tegen de actuele rente. Sommige geldverstrekkers werken met een gemiddelde rente over het geheel, anderen houden de leningdelen gescheiden. Controleer in de voorwaarden van de geldverstrekker de termijn waarbinnen de nieuwe woning moet worden gefinancierd en of er een volledige acceptatietoets plaatsvindt. Ik leg in het dossier vast welke leningdelen worden meegenomen en tegen welke rente het extra deel wordt afgesloten.`}
  ]},
 {id:'vbd-004',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-12T12:35:00',views:103,tags:['annuiteit','lineair','aflosvorm'],beste:'vbd-004-a1',
  titel:'Annuitair of lineair aflossen voor een klant met een stijgend inkomen?',
  body:`Een jonge klant verwacht de komende jaren een flinke inkomensstijging. Hij vraagt waarom ik annuitair adviseer en niet lineair, omdat hij totaal minder rente betaalt bij lineair. Hoe leggen jullie dit uit?`,
  antwoorden:[
   {id:'vbd-004-a1',auteur:'u5',datum:'2025-10-13T06:24:00',rA:{u7:5,u8:4},rAdv:{u7:5,u8:4},body:`Bij lineair aflossen zijn de bruto lasten in het begin het hoogst en dalen ze daarna. Bij annuitair zijn de bruto lasten gelijk, waardoor er in de eerste jaren meer ruimte is. Klopt het dat lineair over de looptijd minder rente kost? Ja, omdat je sneller aflost. Bij een verwachte inkomensstijging past annuitair vaak beter bij het verloop van het inkomen, maar het blijft maatwerk. Toets wel of de aanvangslasten bij lineair binnen de woonlastennorm passen. In het dossier leg ik beide maandlastenoverzichten en de keuze van de klant vast.`},
   {id:'vbd-004-a2',auteur:'u2',datum:'2025-10-13T12:38:00',rA:{},rAdv:{},body:`Ik laat ook zien wat het verschil netto per maand is in de eerste jaren en wat de klant met die ruimte kan doen, zoals een buffer opbouwen of extra aflossen. Extra aflossen binnen de boetevrije ruimte kan de renteafname van lineair deels benaderen, met behoud van flexibiliteit. Die vergelijking neem ik op in het dossier.`}
  ]},
 {id:'vbd-005',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-16T11:10:00',views:585,tags:['aflossingsvrij','overgangsrecht','oversluiten'],beste:'vbd-005-a1',
  titel:'Oud aflossingsvrij deel behouden bij oversluiten naar een andere geldverstrekker',
  body:`Een klant heeft een aflossingsvrij leningdeel uit de periode voor 2013. Hij wil oversluiten naar een andere geldverstrekker met een lagere rente. Behoudt hij dan het fiscale overgangsrecht voor dat deel?`,
  antwoorden:[
   {id:'vbd-005-a1',auteur:'u5',datum:'2025-10-16T21:47:00',rA:{u3:5},rAdv:{},body:`Het fiscale overgangsrecht is gekoppeld aan de schuld, niet aan de geldverstrekker. Bij oversluiten zonder verhoging kan het overgangsrecht behouden blijven, mits de schuld als eigenwoningschuld doorloopt. Let wel op de acceptatienormen van de nieuwe geldverstrekker: die kan het aflossingsvrije deel beperken tot een maximum ten opzichte van de marktwaarde. Controleer de actuele normen en de voorwaarden van de geldverstrekker. Leg in het dossier vast welk deel onder het overgangsrecht valt, met onderbouwing uit de oude leningstukken.`},
   {id:'vbd-005-a2',auteur:'u8',datum:'2025-10-17T18:13:00',rA:{},rAdv:{},body:`Vanuit compliance: vraag de oude hypotheekakte of een overzicht op waaruit de ingangsdatum en aflosvorm blijken. Zonder die onderbouwing kun je achteraf niet aantonen dat het overgangsrecht van toepassing was. Neem dat document op in het dossier.`}
  ]},
 {id:'vbd-006',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-19T14:50:00',views:86,tags:['rente-aanbod','geldigheid','bereidstellingsprovisie'],beste:null,
  titel:'Offerte loopt af terwijl de woning nog niet is opgeleverd',
  body:`Bij een nieuwbouwwoning dreigt de geldigheid van het rentevoorstel af te lopen voordat de bouw klaar is. Welke opties hebben jullie gebruikt om dat op te vangen?`,
  antwoorden:[
   {id:'vbd-006-a1',auteur:'u4',datum:'2025-10-19T22:08:00',rA:{u6:4},rAdv:{u6:4},body:`Er zijn een paar routes, afhankelijk van de geldverstrekker.
- Verlenging van de offerte, soms tegen bereidstellingsprovisie over het niet opgenomen deel.
- Bij nieuwbouw wordt de akte vaak al bij de start van de bouw gepasseerd en loopt het bouwdepot; dan speelt de offertetermijn minder.
- Kijk of de rente bij passeren wordt herzien als die lager is (rentedaalclausule).
Controleer de voorwaarden van de geldverstrekker over verlenging en kosten. Leg de afspraken en de bijbehorende kosten vast in het dossier.`}
  ]},
 {id:'vbd-007',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-23T08:45:00',views:255,tags:['bouwdepot','rente','nieuwbouw'],beste:'vbd-007-a1',
  titel:'Rentevergoeding op het bouwdepot: hoe rekenen jullie dit door?',
  body:`Een klant vraagt waarom hij rente betaalt over het hele bedrag terwijl het bouwdepot nog niet is opgenomen. Hoe leggen jullie de depotrente uit en nemen jullie dit mee in de maandlasten?`,
  antwoorden:[
   {id:'vbd-007-a1',auteur:'u1',datum:'2025-10-23T20:49:00',rA:{u5:5,u3:4},rAdv:{u5:5,u3:4},body:`Over het volledige leningbedrag betaal je hypotheekrente, en over het saldo in het bouwdepot ontvang je een depotvergoeding. Die vergoeding is vaak gelijk aan of iets lager dan de hypotheekrente; controleer de voorwaarden van de geldverstrekker. Netto betaalt de klant dus vooral rente over het deel dat al is uitbetaald. Ik maak een overzicht van de verwachte opnames en de bijbehorende netto lasten tijdens de bouw. In het dossier leg ik de depotvoorwaarden en de looptijd van het depot vast.`}
  ]},
 {id:'vbd-008',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-27T07:05:00',views:236,tags:['oversluiten','boeterente','vergoeding'],beste:'vbd-008-a1',
  titel:'Hoe berekenen geldverstrekkers de vergoeding bij vervroegd aflossen?',
  body:`Een klant wil oversluiten en schrikt van de opgegeven vergoeding. Hij vraagt hoe die tot stand komt. Kan iemand de systematiek kort uitleggen zodat ik het helder aan de klant kan vertellen?`,
  antwoorden:[
   {id:'vbd-008-a1',auteur:'u5',datum:'2025-10-28T04:48:00',rA:{u4:5,u1:4,u7:3},rAdv:{u1:4,u7:3},body:`De vergoeding is bedoeld om het financiele nadeel van de geldverstrekker te dekken. Grofweg is het het renteverschil tussen de contractrente en een vergelijkingsrente, over het bedrag boven de boetevrije ruimte, voor de resterende rentevaste periode, contant gemaakt. Welke vergelijkingsrente wordt gebruikt verschilt per geldverstrekker. Wettelijk mag de vergoeding niet hoger zijn dan het werkelijke financiele nadeel. Vraag altijd een schriftelijke berekening op en leg die vast in het dossier.`},
   {id:'vbd-008-a2',auteur:'u4',datum:'2025-10-28T20:33:00',rA:{},rAdv:{},body:`Tip: check of de klant in het lopende jaar al boetevrij heeft afgelost en of er boetevrije momenten zijn, zoals bij verkoop van de woning of overlijden. Soms scheelt het om de boetevrije ruimte eerst te benutten en daarna over te sluiten. Leg de gebruikte boetevrije ruimte vast in het dossier.`}
  ]},
 {id:'vbd-009',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-10-30T19:55:00',views:231,tags:['energielabel','rentekorting','duurzaamheid'],beste:null,
  titel:'Rentekorting op basis van energielabel bij lopende hypotheek',
  body:`Een klant heeft na verduurzaming een beter energielabel. Kan hij tijdens de rentevaste periode alsnog een rentekorting krijgen, en wat moet hij daarvoor aanleveren?`,
  antwoorden:[
   {id:'vbd-009-a1',auteur:'u4',datum:'2025-10-31T07:40:00',rA:{},rAdv:{},body:`Een aantal geldverstrekkers past een lopende rente aan als er een nieuw, beter energielabel wordt aangeleverd, anderen alleen bij renteverlenging. Het label moet geregistreerd zijn en vaak bij de geldverstrekker worden ingediend via een formulier. Controleer de voorwaarden van de geldverstrekker over het moment van ingang. In het dossier noteer ik het oude en nieuwe label en de datum van indiening.`}
  ]},
 {id:'vbd-010',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-03T16:40:00',views:255,tags:['renteverlenging','rentevoorstel','looptijd'],beste:null,
  titel:'Renteverlengingsvoorstel ontvangen: hoeveel tijd heeft de klant?',
  body:`Een klant krijgt binnenkort een renteverlengingsvoorstel van zijn huidige geldverstrekker. Hij wil weten of hij moet tekenen of kan onderzoeken of oversluiten loont. Hoe pakken jullie dit traject aan?`,
  antwoorden:[
   {id:'vbd-010-a1',auteur:'u4',datum:'2025-11-04T02:40:00',rA:{u1:4,u5:4,u2:3},rAdv:{u1:4,u5:4},body:`De geldverstrekker stuurt het renteverlengingsvoorstel enige tijd voor de renteherzieningsdatum, en geeft een termijn waarbinnen de klant moet kiezen. Hoe lang die termijn is en wat er gebeurt als de klant niet reageert, staat in de voorwaarden; controleer dat per geldverstrekker. Vaak wordt dan automatisch een standaard rentevaste periode gekozen.
Mijn aanpak:
- Zodra het voorstel binnen is: alle rentevaste periodes en de opslagen opvragen.
- Vergelijken met de rente bij andere geldverstrekkers. Op de renteherzieningsdatum kan in de regel boetevrij worden overgesloten; controleer dat.
- Rekenen met de kosten van oversluiten: advies, notaris, taxatie.
- Bespreken of de klant gelijk wil blijven of de hypotheek wil aanpassen (aflossen, looptijd, risicoklasse).
Gebruik oversluiten.html om de kosten af te zetten tegen het renteverschil. In het dossier leg ik vast welke opties zijn vergeleken en waarom de klant tekent of overstapt.`}
  ]},
 {id:'vbd-011',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-07T14:30:00',views:63,tags:['rentevast','renteherziening','variabel'],beste:null,
  titel:'Wanneer adviseren jullie een variabele rente?',
  body:`Een klant met ruim vermogen en een lage leenbehoefte vraagt naar variabele rente omdat hij op korte termijn extra wil aflossen. In welke situaties vinden jullie variabele rente passend?`,
  antwoorden:[
   {id:'vbd-011-a1',auteur:'u2',datum:'2025-11-07T18:40:00',rA:{u5:5},rAdv:{u5:5},body:`Variabele rente kan passen als de klant het renterisico makkelijk kan dragen en flexibiliteit belangrijk is, bijvoorbeeld omdat hij binnen afzienbare tijd fors wil aflossen. Variabel afgeloste bedragen zijn vaak boetevrij; controleer de voorwaarden van de geldverstrekker. Ik reken een scenario door waarin de rente stijgt en toets of de klant dat comfortabel kan opvangen. Ook een combinatie, met een deel variabel en een deel vast, is een optie. Leg het scenario en de risicobereidheid vast in het dossier.`},
   {id:'vbd-011-a2',auteur:'u1',datum:'2025-11-08T06:52:00',rA:{u6:4,u3:5,u5:4,u7:3},rAdv:{u3:5},body:`Let op: bij de toetsing van de leencapaciteit geldt bij een korte rentevaste periode een andere toetsrente. Check de actuele normen. Bij een lage leenbehoefte is dat meestal geen probleem, maar leg het wel vast.`}
  ]},
 {id:'vbd-012',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-10T12:05:00',views:508,tags:['verhuisregeling','overbrugging','termijn'],beste:'vbd-012-a1',
  titel:'Verhuisregeling bij tijdelijk wonen in een huurwoning',
  body:`Een klant verkoopt zijn woning en gaat eerst een tijd huren voordat hij een nieuwe woning koopt. Kan hij zijn rente later alsnog meenemen via de verhuisregeling?`,
  antwoorden:[
   {id:'vbd-012-a1',auteur:'u1',datum:'2025-11-11T10:04:00',rA:{u4:3,u7:4,u3:5,u8:5},rAdv:{u4:3,u8:5},body:`Dat hangt sterk af van de geldverstrekker. Veel verhuisregelingen vereisen dat de nieuwe hypotheek binnen een bepaalde termijn na aflossing van de oude wordt aangevraagd of afgesloten. Er zijn ook geldverstrekkers die een langere termijn hanteren of een rentemeeneemregeling bij latere aankoop kennen. Controleer de voorwaarden en vraag het zo nodig schriftelijk na. Wijs de klant erop dat als de termijn verstrijkt, hij een vergoeding kan moeten betalen of de rente niet meer kan meenemen. Leg dit vast in het dossier.`},
   {id:'vbd-012-a2',auteur:'u5',datum:'2025-11-12T00:50:00',rA:{u7:3,u8:3},rAdv:{},body:`Denk ook aan de fiscale kant: na verkoop kan een eigenwoningreserve ontstaan en de bijleenregeling gaat spelen bij de nieuwe woning. Dat staat los van de rente, maar hoort in hetzelfde gesprek. Ik noteer in het dossier dat dit besproken is.`}
  ]},
 {id:'vbd-013',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-14T12:00:00',views:507,tags:['extra aflossen','boetevrij','annuiteit'],beste:'vbd-013-a1',
  titel:'Extra aflossen: lagere maandlast of kortere looptijd?',
  body:`Een klant wil een bedrag extra aflossen binnen de boetevrije ruimte. Hij kan kiezen tussen een lagere maandlast of dezelfde maandlast met kortere looptijd. Wat adviseren jullie en waar letten jullie op?`,
  antwoorden:[
   {id:'vbd-013-a1',auteur:'u2',datum:'2025-11-15T05:20:00',rA:{},rAdv:{},body:`Beide zijn verdedigbaar; het hangt af van de doelen. Een lagere maandlast geeft ruimte in het budget, een kortere looptijd leidt tot een lagere totale rentelast. Let op:
- Niet elke geldverstrekker biedt beide opties; controleer de voorwaarden.
- Een lagere schuld kan ook de risico-opslag verlagen als de verhouding lening tot waarde in een lagere klasse valt.
- Houd voldoende liquide buffer achter de hand.
In het dossier leg ik de keuze en de motivatie van de klant vast.`},
   {id:'vbd-013-a2',auteur:'u4',datum:'2025-11-16T02:07:00',rA:{u2:5},rAdv:{u2:5},body:`Goed punt van de risico-opslag. Ik vraag na extra aflossing altijd of de geldverstrekker de rente automatisch aanpast of dat de klant dat moet aanvragen met een nieuwe waardebepaling. Leg die bevestiging vast in het dossier.`}
  ]},
 {id:'vbd-014',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-18T11:20:00',views:282,tags:['risicoklasse','LTV','rente'],beste:'vbd-014-a1',
  titel:'Lagere rente door gestegen woningwaarde: hoe vraag je dat aan?',
  body:`De woning van een klant is flink in waarde gestegen. Daardoor valt de verhouding tussen lening en marktwaarde waarschijnlijk in een lagere risicoklasse. Hoe gaan geldverstrekkers hiermee om en wat moet de klant aanleveren?`,
  antwoorden:[
   {id:'vbd-014-a1',auteur:'u4',datum:'2025-11-18T18:46:00',rA:{u6:4,u8:3},rAdv:{},body:`Veel geldverstrekkers passen de risico-opslag aan als de klant een nieuwe waardebepaling aanlevert, bijvoorbeeld een gevalideerd taxatierapport of een geaccepteerde modelmatige waardering. Sommigen doen dit alleen op verzoek, anderen alleen bij renteverlenging. Controleer de voorwaarden en de acceptatie van het type waardebepaling. Weeg de kosten van de taxatie af tegen de verwachte rentebesparing. Leg de nieuwe waarde en de aangevraagde aanpassing vast in het dossier.`}
  ]},
 {id:'vbd-015',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-21T17:10:00',views:346,tags:['NHG','rente','oversluiten'],beste:null,
  titel:'NHG behouden bij oversluiten met verhoging',
  body:`Een klant heeft een hypotheek met NHG en wil oversluiten met een kleine verhoging voor een verbouwing. Kan de NHG behouden blijven en wat betekent dat voor de rente?`,
  antwoorden:[
   {id:'vbd-015-a1',auteur:'u5',datum:'2025-11-21T19:14:00',rA:{},rAdv:{},body:`Oversluiten met NHG kan, mits de nieuwe lening binnen de geldende NHG-normen en kostengrens valt. Bij een verhoging gelden aanvullende voorwaarden, bijvoorbeeld over het doel van de verhoging. Raadpleeg de actuele voorwaarden en normen van NHG. Een hypotheek met NHG heeft meestal een lagere rente, wat het verschil met de borgtochtprovisie vaak goedmaakt. Leg de toets aan de NHG-voorwaarden vast in het dossier.`},
   {id:'vbd-015-a2',auteur:'u1',datum:'2025-11-22T17:22:00',rA:{u3:3},rAdv:{},body:`Praktisch: let op dat de borgtochtprovisie opnieuw verschuldigd is over het nieuwe bedrag. Neem dat mee in de kostenvergelijking. Leg de kosten ook vast in het dossier.`}
  ]},
 {id:'vbd-016',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-25T20:05:00',views:356,tags:['rentemiddeling','vergelijking','advies'],beste:'vbd-016-a1',
  titel:'Moet rentemiddeling ook als adviestraject worden vastgelegd?',
  body:`Een klant vraagt alleen om rentemiddeling aan te vragen bij zijn bestaande geldverstrekker. Is dat execution only, of moeten we hier een volledig advies omheen leggen?`,
  antwoorden:[
   {id:'vbd-016-a1',auteur:'u8',datum:'2025-11-26T09:45:00',rA:{u6:5},rAdv:{u6:5},body:`Als je de klant adviseert over het wel of niet doen van rentemiddeling, is dat advies en gelden de bijbehorende zorgplichten. Kies je voor bemiddeling zonder advies, dan moet dat duidelijk zijn afgesproken en vastgelegd, en moet je nagaan of dat passend is voor deze klant. In de praktijk is een vergelijking met niets doen en eventueel oversluiten al snel advies. Leg in het dossier vast welke dienst is afgesproken, wat je hebt onderzocht en wat de klant heeft besloten.`},
   {id:'vbd-016-a2',auteur:'u4',datum:'2025-11-27T07:21:00',rA:{u7:4},rAdv:{u7:4},body:`Ik werk hier met een kort adviestraject: inventarisatie, berekening van rentemiddeling versus doorlopen, en een vastgelegde keuze. Dat kost weinig extra tijd en geeft een veel sterker dossier. Het advies staat dan ook in het rapport zodat de klant het kan teruglezen.`}
  ]},
 {id:'vbd-017',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-11-29T15:05:00',views:197,tags:['rentedaalclausule','offerte','rente'],beste:'vbd-017-a1',
  titel:'Rentedaalclausule: wanneer geldt de lagere rente?',
  body:`De rente is gedaald na het uitbrengen van de offerte. Hoe werkt de rentedaalclausule precies en moet ik daar als adviseur iets voor doen?`,
  antwoorden:[
   {id:'vbd-017-a1',auteur:'u1',datum:'2025-11-29T18:30:00',rA:{u3:5,u8:4},rAdv:{u8:4},body:`Bij een rentedaalclausule krijgt de klant bij het passeren de laagste rente van de offerterente en de actuele rente voor dezelfde rentevaste periode en risicoklasse. Soms gebeurt dat automatisch, soms moet het worden aangevraagd. Bij sommige geldverstrekkers kost de clausule een opslag of is hij alleen beschikbaar bij langere offertetermijnen. Controleer de voorwaarden van de geldverstrekker. Ik noteer in het dossier welke rente is geoffreerd en welke rente bij passeren is toegepast.`}
  ]},
 {id:'vbd-018',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-03T14:40:00',views:381,tags:['aflosvorm','bankspaar','herstructureren'],beste:null,
  titel:'Bestaande bankspaarrekening bij oversluiten: voortzetten of verrekenen?',
  body:`Een klant heeft een hypotheek met een gekoppelde bankspaarrekening. Bij oversluiten naar een andere geldverstrekker vraag ik me af of de spaarrekening mee kan of moet worden verrekend. Wat zijn jullie ervaringen?`,
  antwoorden:[
   {id:'vbd-018-a1',auteur:'u5',datum:'2025-12-04T11:49:00',rA:{u1:4,u6:5,u8:5},rAdv:{u1:4,u6:5},body:`Een bankspaarrekening is fiscaal en contractueel gekoppeld aan de lening. Bij oversluiten kan de spaarwaarde vaak worden overgedragen naar een nieuwe bankspaarvorm, mits de nieuwe geldverstrekker dat product nog aanbiedt en de fiscale voorwaarden blijven gelden. Anders wordt de spaarwaarde meestal verrekend met de lening. Laat de fiscale gevolgen goed uitzoeken en controleer de voorwaarden van beide geldverstrekkers. Leg de keuze en de fiscale toets vast in het dossier.`},
   {id:'vbd-018-a2',auteur:'u2',datum:'2025-12-05T05:41:00',rA:{u7:5},rAdv:{u7:5},body:`Bekijk ook of verrekenen nadelig is voor een eventuele vrijstelling. Bij twijfel loont het om fiscale ondersteuning te vragen voordat de klant tekent. Leg de uitkomst van die toets vast in het dossier.`}
  ]},
 {id:'vbd-019',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-06T15:10:00',views:209,tags:['overlijdensrisico','aflosvorm','verzekering'],beste:'vbd-019-a1',
  titel:'Overlijdensrisicoverzekering aanpassen na wijziging van de aflosvorm',
  body:`Bij een herstructurering wordt een aflossingsvrij deel omgezet naar annuitair. De klant heeft een gelijkblijvende overlijdensrisicoverzekering. Moet die worden aangepast?`,
  antwoorden:[
   {id:'vbd-019-a1',auteur:'u3',datum:'2025-12-06T17:33:00',rA:{},rAdv:{},body:`Niet per se, maar het is wel een moment om de dekking opnieuw te beoordelen. Bij een annuitaire lening daalt de schuld, dus een gelijkblijvende dekking wordt relatief ruimer. Soms is een annuitair dalende dekking goedkoper, maar dat vraagt een nieuwe verzekering met mogelijk een nieuwe gezondheidswaarborg. Controleer of de geldverstrekker een verpanding verplicht stelt. Leg de afweging en de keuze vast in het dossier.`}
  ]},
 {id:'vbd-020',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-10T10:15:00',views:580,tags:['looptijd','30 jaar','rentevast'],beste:null,
  titel:'Rentevaste periode langer dan de resterende looptijd',
  body:`Een klant heeft nog ongeveer achttien jaar looptijd en wil de rente voor twintig jaar vastzetten. Kan dat, en wat zijn de gevolgen?`,
  antwoorden:[
   {id:'vbd-020-a1',auteur:'u1',datum:'2025-12-10T18:15:00',rA:{u4:4,u5:4,u2:4},rAdv:{u4:4,u5:4},body:`Meestal niet. Geldverstrekkers staan doorgaans geen rentevaste periode toe die langer is dan de resterende looptijd van het leningdeel. De klant kan dan kiezen voor de langste periode die wel binnen de looptijd past, of de looptijd verlengen.
Let bij verlengen van de looptijd op:
- Fiscaal: de renteaftrek is beperkt tot de resterende termijn van de dertigjaarstermijn. Een langere looptijd betekent na die termijn geen aftrek meer.
- Toetsing: een langere looptijd is een wijziging waarvoor de geldverstrekker opnieuw kan toetsen.
- Pensioen: een langere looptijd kan doorlopen na de AOW-datum.
Bekijk ook of de klant extra aflost, zodat een kortere looptijd beter past. Wat de klant eigenlijk zoekt, is zekerheid tot het einde. Een rentevaste periode tot de einddatum, voor zover aangeboden, levert dat ook.
Leg in het dossier vast waarom voor deze rentevaste periode is gekozen en wat de fiscale gevolgen zijn.`}
  ]},
 {id:'vbd-021',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-14T13:45:00',views:183,tags:['oversluiten','kosten','advies'],beste:'vbd-021-a1',
  titel:'Wanneer loont oversluiten niet?',
  body:`Klanten vragen regelmatig of oversluiten zin heeft nu de rente lager is dan hun contractrente. Wat zijn voor jullie signalen dat oversluiten waarschijnlijk niet loont?`,
  antwoorden:[
   {id:'vbd-021-a1',auteur:'u4',datum:'2025-12-15T08:46:00',rA:{},rAdv:{},body:`Een paar signalen die ik snel check:
- Een korte resterende rentevaste periode: de besparing is dan beperkt en wachten kan goedkoper zijn.
- Een hoge vergoeding wegens vervroegde aflossing ten opzichte van het renteverschil.
- Hoge eenmalige kosten zoals notaris, taxatie en advies bij een lage schuld.
- Een gunstig overgangsrecht of productkenmerk dat verloren gaat.
Ik maak altijd een break-evenberekening en leg die in het dossier vast, ook als de klant uiteindelijk niet oversluit.`},
   {id:'vbd-021-a2',auteur:'u2',datum:'2025-12-16T00:36:00',rA:{u1:4,u4:5},rAdv:{u1:4},body:`Daarnaast: kijk of rentemiddeling of renteverlenging bij de huidige geldverstrekker een goedkoper alternatief is. Soms is de winst vooral te halen uit een lagere risicoklasse. Die alternatieven neem ik altijd op in de vergelijking.`}
  ]},
 {id:'vbd-022',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-17T07:45:00',views:330,tags:['meeneemregeling','verkoop','termijn'],beste:'vbd-022-a1',
  titel:'Verhuisregeling en een gedeeltelijk afgeloste hypotheek',
  body:`Een klant verkoopt en koopt een goedkopere woning. Een deel van de hypotheek wordt afgelost uit de overwaarde. Is de aflossing van dat deel boetevrij als hij de rest meeneemt?`,
  antwoorden:[
   {id:'vbd-022-a1',auteur:'u1',datum:'2025-12-17T19:51:00',rA:{},rAdv:{},body:`Bij verkoop van de woning is aflossing meestal boetevrij volgens de voorwaarden, maar als de klant een deel meeneemt naar de nieuwe woning ligt het per geldverstrekker anders. Sommigen beschouwen het afgeloste deel als boetevrij vanwege de verkoop, anderen rekenen een vergoeding over het deel boven de boetevrije ruimte. Controleer de voorwaarden van de geldverstrekker en vraag een schriftelijke bevestiging. Leg in het dossier vast welke delen worden afgelost en welke worden meegenomen, met de bijbehorende kosten.`}
  ]},
 {id:'vbd-023',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-21T15:00:00',views:460,tags:['rente','risico-opslag','offerte'],beste:null,
  titel:'Waarom verschilt de rente in de offerte van de rentetabel?',
  body:`Een klant vergelijkt de rente in zijn offerte met de rentetabel op internet en ziet een verschil. Welke opslagen en kortingen moeten we standaard uitleggen?`,
  antwoorden:[
   {id:'vbd-023-a1',auteur:'u4',datum:'2025-12-22T03:36:00',rA:{u6:4,u8:5,u5:4,u3:4},rAdv:{u6:4,u8:5,u3:4},body:`Veelvoorkomende verklaringen:
- Risico-opslag op basis van de verhouding lening tot marktwaarde.
- Opslag of korting voor aflosvorm, bijvoorbeeld voor aflossingsvrij.
- Korting voor energielabel of NHG.
- De rentetabel kan op een andere datum zijn gepubliceerd dan de offerte.
Ik leg dit uit aan de hand van de offerte en noteer de toegepaste opslagen en kortingen in het dossier.`}
  ]},
 {id:'vbd-024',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-24T21:35:00',views:5,tags:['rentevast','pensioen','looptijd'],beste:'vbd-024-a1',
  titel:'Rentevaste periode die doorloopt na pensionering',
  body:`Een klant gaat over enkele jaren met pensioen en wil een lange rentevaste periode. Zijn inkomen daalt na pensionering. Hoe nemen jullie dat mee in de keuze voor de rentevaste periode?`,
  antwoorden:[
   {id:'vbd-024-a1',auteur:'u7',datum:'2025-12-25T03:41:00',rA:{},rAdv:{},body:`Ik breng eerst het pensioeninkomen goed in kaart en toets of de lasten na pensionering betaalbaar blijven. Een lange rentevaste periode geeft zekerheid over de lasten precies in de periode waarin het inkomen lager en minder flexibel is, wat vaak juist passend is. Wel kost zekerheid geld; zet de meerkosten af tegen het risico. Ik leg de pensioenprognose, het lastenoverzicht na pensionering en de keuze vast in het dossier.`},
   {id:'vbd-024-a2',auteur:'u5',datum:'2025-12-25T11:55:00',rA:{u7:4,u4:4},rAdv:{u7:4},body:`Kijk ook naar aflossen voor of rond pensionering, bijvoorbeeld uit vrij vermogen, zodat de schuld en de lasten lager worden. De boetevrije ruimte per jaar kun je in de jaren ervoor al gebruiken. Leg het aflosplan vast in het dossier.`}
  ]},
 {id:'vbd-025',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2025-12-28T11:20:00',views:477,tags:['rentevast','dossier','vastleggen'],beste:'vbd-025-a1',
  titel:'Welke rentegegevens leggen jullie vast in het adviesdossier?',
  body:`Bij een dossiercontrole kwam de vraag of we voldoende hadden vastgelegd over de rentekeuze. Welke gegevens over rente en rentevaste periode leggen jullie standaard vast?`,
  antwoorden:[
   {id:'vbd-025-a1',auteur:'u8',datum:'2025-12-29T08:15:00',rA:{u2:5,u6:4},rAdv:{},body:`Ik zou minimaal vastleggen:
- De vergeleken rentevaste periodes en bijbehorende rentes, met datum en bron.
- De risicobereidheid van de klant op het gebied van rente en maandlast.
- Een scenario met een hogere rente bij renteherziening.
- De gekozen periode en de motivering.
- Toegepaste opslagen, kortingen en eventuele rentedaalclausule.
Zo is de keuze achteraf navolgbaar voor zowel de klant als een toezichthouder.`},
   {id:'vbd-025-a2',auteur:'u6',datum:'2025-12-30T00:50:00',rA:{u1:3},rAdv:{u1:3},body:`In ons adviespakket kun je een vergelijkingsoverzicht van rentevaste periodes als bijlage opslaan bij het advies. Dan staat de datum automatisch op het document en hoef je het niet los te bewaren. Controleer wel of de bijlage ook bij het definitieve advies is gekoppeld.`}
  ]},
 {id:'vbd-026',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-01T10:50:00',views:483,tags:['rentebedenktijd','renteverlenging','rente'],beste:'vbd-026-a1',
  titel:'Rentebedenktijd bij renteverlenging: hoe werkt dat in de praktijk?',
  body:`Een klant heeft een rentevoorstel voor verlenging gekregen met rentebedenktijd. Hij vraagt of hij nu moet kiezen of beter kan wachten. Hoe gebruiken jullie de rentebedenktijd in het advies?`,
  antwoorden:[
   {id:'vbd-026-a1',auteur:'u4',datum:'2026-01-02T07:38:00',rA:{},rAdv:{},body:`Bij rentebedenktijd legt de klant een rentevaste periode vast, maar krijgt hij tot de ingangsdatum de laagste rente als de rente daalt. Controleer bij de geldverstrekker hoe lang de bedenktijd is en of de klant daarbinnen nog van rentevaste periode kan wisselen. Mijn advies is meestal om tijdig een keuze te maken, zodat de klant beschermd is tegen een stijging. In het dossier leg ik de gekozen periode, de geboden rente en de datum van keuze vast.`},
   {id:'vbd-026-a2',auteur:'u1',datum:'2026-01-02T16:16:00',rA:{u7:3,u8:4,u5:3},rAdv:{u7:3,u8:4},body:`Let ook op dat de bedenktijd niet altijd voor alle periodes of risicoklassen geldt. Bij sommige geldverstrekkers moet je de lagere rente actief aanvragen. Leg de datum van de aanvraag vast in het dossier.`}
  ]},
 {id:'vbd-027',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-04T18:45:00',views:98,tags:['restschuld','oversluiten','financiering'],beste:'vbd-027-a1',
  titel:'Restschuld meefinancieren bij verhuizing: welke rente geldt?',
  body:`Een klant verkoopt met verlies en wil de restschuld meefinancieren in de nieuwe hypotheek. Krijgt het restschulddeel een andere rente dan de rest en wat moet ik controleren?`,
  antwoorden:[
   {id:'vbd-027-a1',auteur:'u5',datum:'2026-01-05T12:39:00',rA:{u6:5},rAdv:{u6:5},body:`Een meegefinancierde restschuld is vaak een apart leningdeel met een eigen rente, soms met een opslag. De aflosvorm moet in de regel annuitair of lineair zijn en de looptijd kan beperkt zijn. Fiscaal is de rente over een restschuld onder voorwaarden aftrekbaar; laat dat goed toetsen. Controleer de acceptatievoorwaarden van de geldverstrekker en de geldende normen. Leg de berekening van de restschuld en de fiscale behandeling vast in het dossier.`}
  ]},
 {id:'vbd-028',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-08T10:55:00',views:33,tags:['spaarhypotheek','oversluiten','fiscaal'],beste:'vbd-028-a1',
  titel:'Spaarhypotheek bij oversluiten: koppeling met de verzekering',
  body:`Een klant heeft een spaarhypotheek waarbij de spaarverzekering aan de lening is gekoppeld. Bij oversluiten naar een andere geldverstrekker is de rente van het spaardeel aan de leningrente gekoppeld. Wat zijn de aandachtspunten?`,
  antwoorden:[
   {id:'vbd-028-a1',auteur:'u3',datum:'2026-01-09T09:56:00',rA:{},rAdv:{},body:`Bij een spaarhypotheek is het rendement op de verzekering gelijk aan de hypotheekrente. Bij oversluiten wordt die koppeling vaak doorbroken, waardoor de verzekering anders gaat renderen of moet worden afgekocht. Afkoop kan fiscale gevolgen hebben. Vraag bij de verzekeraar de mogelijkheden op: voortzetten, premievrij maken of afkopen. Leg de waarde, de gekozen optie en de fiscale toets vast in het dossier.`},
   {id:'vbd-028-a2',auteur:'u5',datum:'2026-01-09T18:13:00',rA:{u8:5,u2:5},rAdv:{u8:5},body:`Fiscaal is het belangrijk om te weten of de verzekering onder een vrijstelling valt. Afkoop of wijziging kan die vrijstelling raken. Zonder toets van een fiscalist zou ik hier niet adviseren om af te kopen.`}
  ]},
 {id:'vbd-029',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-12T09:15:00',views:457,tags:['beleggingshypotheek','aflosvorm','risico'],beste:null,
  titel:'Beleggingshypotheek met tegenvallend rendement: omzetten naar annuitair?',
  body:`Een klant heeft een beleggingshypotheek waarbij de verwachte waarde op einddatum de schuld niet dekt. Hij wil weten of omzetten naar annuitair verstandig is. Hoe pakken jullie dit aan?`,
  antwoorden:[
   {id:'vbd-029-a1',auteur:'u2',datum:'2026-01-12T22:56:00',rA:{},rAdv:{},body:`Ik begin met een prognose van de beleggingswaarde op einddatum onder verschillende rendementsscenario's en vergelijk die met de schuld. Daarna bekijk ik de opties:
- Inleg verhogen of extra storten.
- Een deel van de lening omzetten naar annuitair, met hogere maandlasten.
- Beleggingswaarde gebruiken om af te lossen.
Let op de fiscale positie, het overgangsrecht en eventuele kosten. Controleer de voorwaarden van de geldverstrekker. Leg de scenario's en de keuze vast in het dossier.`},
   {id:'vbd-029-a2',auteur:'u5',datum:'2026-01-13T02:50:00',rA:{},rAdv:{},body:`Bij een beleggingshypotheek met overgangsrecht kan omzetten van een deel naar annuitair de aftrek behouden, maar de fiscale details zijn belangrijk. Laat dat goed controleren voordat je wijzigt. Leg die toets vast in het dossier voordat de wijziging wordt doorgevoerd.`}
  ]},
 {id:'vbd-030',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-16T12:50:00',views:490,tags:['tweede hypotheek','verbouwing','rente'],beste:'vbd-030-a1',
  titel:'Tweede leningdeel voor verbouwing: bij dezelfde of andere geldverstrekker?',
  body:`Een klant wil verbouwen en heeft een lage rente op zijn bestaande hypotheek. Wat zijn de opties om het extra bedrag te financieren zonder de lage rente te verliezen?`,
  antwoorden:[
   {id:'vbd-030-a1',auteur:'u1',datum:'2026-01-17T10:19:00',rA:{u4:4,u6:5,u2:4,u3:4},rAdv:{u2:4},body:`Opties die ik meestal vergelijk:
- Verhoging bij de huidige geldverstrekker: het bestaande deel blijft met de lage rente doorlopen, het extra deel tegen de actuele rente.
- Een tweede hypotheek bij een andere geldverstrekker: dat is niet altijd mogelijk en de rente is vaak hoger.
- Verbouwing deels uit eigen middelen.
Controleer of de verhoging een nieuwe hypotheekakte vereist en welke kosten dat meebrengt. Leg de vergelijking vast in het dossier.`}
  ]},
 {id:'vbd-031',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-19T22:20:00',views:489,tags:['rente','toetsrente','leencapaciteit'],beste:'vbd-031-a1',
  titel:'Toetsrente bij korte rentevaste periode: hoe werkt dat?',
  body:`Bij een korte rentevaste periode komt de leencapaciteit lager uit dan bij een lange periode. Een klant snapt niet waarom. Hoe leggen jullie de toetsrente uit?`,
  antwoorden:[
   {id:'vbd-031-a1',auteur:'u4',datum:'2026-01-20T06:40:00',rA:{u1:4,u2:5},rAdv:{u1:4,u2:5},body:`Bij een rentevaste periode korter dan de wettelijke grens wordt niet getoetst met de werkelijke rente, maar met een vastgestelde toetsrente. Dat beschermt de klant tegen te hoge lasten bij een rentestijging. Voor periodes vanaf die grens mag de werkelijke rente worden gebruikt. Raadpleeg de actuele normen voor de hoogte van de toetsrente en de grens. In het dossier leg ik vast met welke rente is getoetst.`},
   {id:'vbd-031-a2',auteur:'u1',datum:'2026-01-20T14:36:00',rA:{u6:5},rAdv:{u6:5},body:`Ik laat klanten ook zien dat de lagere leencapaciteit geen oordeel over hen is, maar een gevolg van de regels. Dat helpt in het gesprek. Ik noteer in het dossier met welke toetsrente is gerekend.`}
  ]},
 {id:'vbd-032',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-23T11:40:00',views:171,tags:['overwaarde','oversluiten','consumptief'],beste:'vbd-032-a1',
  titel:'Overwaarde opnemen voor een auto: aftrekbaar of niet?',
  body:`Een klant wil bij het oversluiten extra lenen om een auto te kopen. Hij gaat ervan uit dat de rente aftrekbaar is. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbd-032-a1',auteur:'u5',datum:'2026-01-23T14:25:00',rA:{u8:5},rAdv:{},body:`Rente is alleen aftrekbaar als de lening is aangegaan voor verwerving, verbetering of onderhoud van de eigen woning en aan de overige fiscale voorwaarden voldoet. Een autolening via de hypotheek is dus een box 3-schuld, ook al heeft het hypothecaire zekerheid. Daarnaast vragen veel geldverstrekkers een bestedingsdoel en geldt voor consumptieve bestedingen vaak een maximum of een opslag. Ik vraag me ook af of het passend is om een auto over een lange looptijd te financieren. Leg het bestedingsdoel, de fiscale behandeling en de afweging vast in het dossier.`},
   {id:'vbd-032-a2',auteur:'u8',datum:'2026-01-24T14:08:00',rA:{},rAdv:{},body:`Belangrijk: wees duidelijk dat je de klant hebt gewezen op het ontbreken van renteaftrek en op de totale kosten over de looptijd. Bij een klacht is dat een kernpunt. Laat de klant die uitleg bij voorkeur schriftelijk bevestigen.`}
  ]},
 {id:'vbd-033',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-27T14:35:00',views:444,tags:['verhuisregeling','nieuwbouw','bouwtijd'],beste:null,
  titel:'Verhuisregeling bij nieuwbouw met lange bouwtijd',
  body:`Een klant koopt nieuwbouw en wil zijn bestaande rente meenemen. De oplevering duurt nog lang. Ik twijfel of de termijn van de verhuisregeling daarvoor ruim genoeg is.`,
  antwoorden:[
   {id:'vbd-033-a1',auteur:'u5',datum:'2026-01-28T01:35:00',rA:{u1:4,u4:5,u2:3},rAdv:{u1:4,u4:5},body:`Terechte twijfel. De verhuisregeling heeft een termijn die loopt vanaf het moment van aflossing van de oude hypotheek, en die termijn verschilt per geldverstrekker. Controleer de voorwaarden.
Bij nieuwbouw zijn er twee scenario's:
- De klant blijft in de oude woning tot de oplevering. Dan wordt de oude hypotheek pas na de oplevering afgelost en is de timing meestal geen probleem. Er is dan wel een overbrugging nodig als de nieuwe hypotheek eerder ingaat (bij het notarieel transport van de grond).
- De klant verkoopt eerst. Dan begint de termijn eerder en kan die te kort zijn.
Alternatief: een offerte met een lange geldigheidsduur voor nieuwbouw, of een renteafspraak die bij de geldverstrekker wordt vastgezet. Let ook op de bouwrente.
In het dossier leg ik vast welke termijn geldt, hoe de planning eruitziet en wat er gebeurt als de bouw vertraagt.`}
  ]},
 {id:'vbd-034',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-01-30T20:10:00',views:448,tags:['rentevast','combinatie','leningdelen'],beste:null,
  titel:'Leningdelen met verschillende rentevaste periodes: zinvol?',
  body:`Een klant wil risico spreiden door leningdelen met verschillende rentevaste periodes af te sluiten. Is dat in de praktijk verstandig en wat zijn de nadelen?`,
  antwoorden:[
   {id:'vbd-034-a1',auteur:'u2',datum:'2026-01-31T16:57:00',rA:{u8:3,u4:3},rAdv:{u8:3,u4:3},body:`Spreiden kan het renterisico verdelen over meerdere momenten. Nadelen zijn dat het overzicht minder is en dat oversluiten of verhuizen complexer wordt omdat de delen op verschillende momenten aflopen. Sommige geldverstrekkers rekenen ook met een minimumbedrag per leningdeel. Ik vind het vooral zinvol als de klant een deel verwacht af te lossen, bijvoorbeeld uit een erfenis of bonus. Leg de reden voor de spreiding en de verwachte momenten vast in het dossier.`}
  ]},
 {id:'vbd-035',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-03T16:05:00',views:452,tags:['oversluiten','notaris','kosten'],beste:'vbd-035-a1',
  titel:'Kosten bij oversluiten in kaart brengen voor de klant',
  body:`Welke kostenposten nemen jullie standaard mee in een oversluitberekening? Ik wil een vaste checklist hanteren, zodat ik geen posten vergeet.`,
  antwoorden:[
   {id:'vbd-035-a1',auteur:'u4',datum:'2026-02-04T05:37:00',rA:{},rAdv:{},body:`Mijn checklist:
- Vergoeding wegens vervroegde aflossing bij de huidige geldverstrekker.
- Notariskosten voor de nieuwe hypotheekakte en doorhaling.
- Taxatie of waardebepaling.
- Advies- en bemiddelingskosten.
- Eventuele NHG-borgtochtprovisie.
- Afsluitkosten of bereidstellingsprovisie bij de nieuwe geldverstrekker.
Daarnaast neem ik de fiscale behandeling van de kosten mee. Leg de berekening vast in het dossier.`},
   {id:'vbd-035-a2',auteur:'u6',datum:'2026-02-04T11:49:00',rA:{u8:5,u7:5,u4:5},rAdv:{u8:5,u7:5,u4:5},body:`In het adviespakket kun je een sjabloon voor oversluitkosten aanmaken, zodat deze posten standaard in de berekening staan. Pas het sjabloon wel aan als er bijzondere kosten spelen. Leg de uiteindelijke berekening per klant vast.`}
  ]},
 {id:'vbd-036',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-06T20:45:00',views:446,tags:['echtscheiding','rente','overname'],beste:'vbd-036-a1',
  titel:'Overname van de hypotheek na scheiding: blijft de rente gelijk?',
  body:`Een van de partners neemt na een scheiding de woning en de hypotheek over. De rente is laag en de rentevaste periode loopt nog jaren door. Blijft die rente staan?`,
  antwoorden:[
   {id:'vbd-036-a1',auteur:'u1',datum:'2026-02-07T10:36:00',rA:{u7:5,u6:5},rAdv:{u6:5},body:`Bij ontslag uit hoofdelijke aansprakelijkheid toetst de geldverstrekker of de achterblijvende partner de lasten alleen kan dragen. Als dat lukt, blijft de bestaande rente vaak doorlopen. Bij een verhoging om de ex-partner uit te kopen geldt voor het extra deel de actuele rente. Controleer de voorwaarden van de geldverstrekker. Leg de toetsing, de overname en de afspraken met de ex-partner vast in het dossier.`},
   {id:'vbd-036-a2',auteur:'u5',datum:'2026-02-08T08:42:00',rA:{},rAdv:{},body:`Fiscaal is het van belang hoe de uitkoop wordt gefinancierd en of er sprake is van een eigenwoningschuld. Laat dit goed toetsen, inclusief de bijleenregeling. Leg de uitkomst van die toets vast in het dossier.`}
  ]},
 {id:'vbd-037',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-10T16:50:00',views:244,tags:['partieel aflossen','vergoeding','boetevrij'],beste:'vbd-037-a1',
  titel:'Boetevrije ruimte: per leningdeel of over de hele lening?',
  body:`Een klant wil extra aflossen en vraagt of de boetevrije ruimte geldt per leningdeel of over de totale hypotheek. Weet iemand hoe dat meestal werkt?`,
  antwoorden:[
   {id:'vbd-037-a1',auteur:'u4',datum:'2026-02-11T10:54:00',rA:{},rAdv:{},body:`Dat verschilt per geldverstrekker. Bij sommigen geldt het percentage over de oorspronkelijke hoofdsom per leningdeel, bij anderen over de totale lening. Ook de peildatum en of ongebruikte ruimte vervalt verschilt. Controleer de algemene voorwaarden. Ik raad aan extra aflossing te doen op het deel met de hoogste rente, mits dat past binnen de voorwaarden. Leg vast welk deel is afgelost en waarom.`}
  ]},
 {id:'vbd-038',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-14T17:35:00',views:100,tags:['looptijd','annuiteit','herstructureren'],beste:null,
  titel:'Looptijd van een annuiteit opnieuw op dertig jaar zetten bij oversluiten',
  body:`Een klant heeft na tien jaar nog twintig jaar looptijd. Bij oversluiten wil hij de looptijd weer op dertig jaar zetten voor lagere lasten. Wat zijn de fiscale gevolgen?`,
  antwoorden:[
   {id:'vbd-038-a1',auteur:'u5',datum:'2026-02-15T08:42:00',rA:{u8:4,u3:4,u7:5},rAdv:{u8:4},body:`Fiscaal geldt voor de eigenwoningschuld een maximale aftrekperiode van dertig jaar die al loopt. Als de looptijd opnieuw dertig jaar wordt, valt de rente na afloop van de resterende fiscale periode niet meer onder de aftrek. Daarnaast moet de schuld voor aftrek in de resterende fiscale looptijd volledig worden afgelost. Een langere looptijd kan dus fiscale nadelen hebben. Laat dit goed toetsen. Leg de resterende fiscale looptijd en de gevolgen vast in het dossier.`},
   {id:'vbd-038-a2',auteur:'u2',datum:'2026-02-15T12:51:00',rA:{},rAdv:{},body:`Bij een langere looptijd zou ik altijd berekenen wat de klant over de totale periode meer aan rente betaalt. Dat zet de lagere maandlast in perspectief. Dat bedrag noteer ik in het adviesrapport.`}
  ]},
 {id:'vbd-039',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-18T08:45:00',views:10,tags:['aflossingsvrij','maximum','acceptatie'],beste:'vbd-039-a1',
  titel:'Hoeveel aflossingsvrij mag er nog bij een nieuwe hypotheek?',
  body:`Een klant met veel eigen vermogen wil een deel aflossingsvrij lenen. Hoe bepalen jullie welk deel aflossingsvrij kan en wat zijn de aandachtspunten?`,
  antwoorden:[
   {id:'vbd-039-a1',auteur:'u1',datum:'2026-02-18T19:44:00',rA:{u3:4,u4:3,u6:4,u8:4},rAdv:{u4:3,u6:4},body:`Voor nieuwe hypotheken geldt een maximum voor het aflossingsvrije deel ten opzichte van de marktwaarde volgens de geldende regels. Daarnaast hanteren geldverstrekkers eigen voorwaarden. Een aflossingsvrij deel valt in box 3 als het niet onder het overgangsrecht valt, zonder renteaftrek. Toets wat het betekent voor de schuld op pensioendatum en de betaalbaarheid daarna. Raadpleeg de actuele normen. Leg de motivering en de toets vast in het dossier.`}
  ]},
 {id:'vbd-040',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-21T14:10:00',views:239,tags:['renteherziening','maandlast','advies'],beste:'vbd-040-a1',
  titel:'Klant schrikt van hoge rente bij renteherziening',
  body:`Een klant heeft binnenkort renteherziening en de nieuwe rente ligt flink hoger dan de oude. Zijn maandlasten stijgen fors. Welke opties bespreken jullie?`,
  antwoorden:[
   {id:'vbd-040-a1',auteur:'u4',datum:'2026-02-21T16:36:00',rA:{u2:5,u5:5,u8:5,u3:5},rAdv:{u2:5,u5:5,u3:5},body:`Opties die ik doorneem:
- Verschillende rentevaste periodes vergelijken, inclusief kortere periodes.
- Extra aflossen uit spaargeld om de schuld en mogelijk de risicoklasse te verlagen.
- Vergelijken met andere geldverstrekkers.
- Aanpassing van aflosvorm of looptijd binnen fiscale en acceptatiegrenzen.
Bij betalingsproblemen adviseer ik vroegtijdig contact op te nemen met de geldverstrekker. Leg de opties en keuzes vast in het dossier.`},
   {id:'vbd-040-a2',auteur:'u2',datum:'2026-02-22T05:20:00',rA:{u4:5},rAdv:{u4:5},body:`Breng ook het volledige budget in kaart. Soms zijn er andere posten waar ruimte te halen valt, zodat de klant niet uit nood voor een te korte rentevaste periode kiest. Leg het budgetoverzicht vast in het dossier.`}
  ]},
 {id:'vbd-041',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-02-25T21:10:00',views:182,tags:['rentemiddeling','lagere rente','aanvraag'],beste:null,
  titel:'Rentemiddeling aanvragen: welke stukken zijn nodig?',
  body:`Ik wil voor een klant rentemiddeling aanvragen. Welke stukken en gegevens vragen geldverstrekkers meestal op? Moet er opnieuw worden getoetst op inkomen?`,
  antwoorden:[
   {id:'vbd-041-a1',auteur:'u1',datum:'2026-02-26T09:19:00',rA:{u2:4,u6:5},rAdv:{u2:4},body:`Bij rentemiddeling wordt meestal niet opnieuw op inkomen getoetst, omdat de lening niet wordt verhoogd. Vaak is een aanvraagformulier voldoende, soms met een kopie identiteitsbewijs. Wil de klant ook een lagere risicoklasse, dan is een nieuwe waardebepaling nodig. Controleer de procedure van de geldverstrekker. Leg de aanvraag en de bevestiging van de nieuwe rente vast in het dossier.`}
  ]},
 {id:'vbd-042',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-01T13:00:00',views:163,tags:['overbrugging','rente','doorstromer'],beste:'vbd-042-a1',
  titel:'Rente op het overbruggingskrediet: hoe nemen jullie dat mee?',
  body:`Bij een doorstromer is een overbruggingskrediet nodig totdat de oude woning is verkocht. De rente daarop is hoger dan de hypotheekrente. Hoe nemen jullie dat mee in het advies?`,
  antwoorden:[
   {id:'vbd-042-a1',auteur:'u4',datum:'2026-03-02T04:27:00',rA:{u7:5,u1:5,u5:3},rAdv:{u5:3},body:`Ik neem de rente over de verwachte overbruggingsperiode op in het lastenoverzicht, plus een scenario waarin de verkoop langer duurt. Een overbruggingskrediet heeft een beperkte looptijd en de rente kan onder voorwaarden aftrekbaar zijn. Controleer de voorwaarden van de geldverstrekker, ook over de maximale looptijd. Leg de dubbele lasten en het langere scenario vast in het dossier.`},
   {id:'vbd-042-a2',auteur:'u5',datum:'2026-03-02T14:28:00',rA:{u7:3,u2:5,u6:4,u8:4},rAdv:{u8:4},body:`Fiscaal: de rente van de oude woning en het overbruggingskrediet kunnen onder voorwaarden tijdelijk aftrekbaar zijn. Controleer de actuele regels. Leg de verwachte termijn van dubbele lasten vast in het dossier.`}
  ]},
 {id:'vbd-043',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-04T15:25:00',views:99,tags:['aflosvorm','spaarrekening','eigen middelen'],beste:'vbd-043-a1',
  titel:'Gespaard geld gebruiken voor aflossen of als buffer houden?',
  body:`Een klant heeft een flinke spaarbuffer en de rente op sparen is lager dan de hypotheekrente. Hij vraagt of hij moet aflossen. Hoe benaderen jullie dit?`,
  antwoorden:[
   {id:'vbd-043-a1',auteur:'u2',datum:'2026-03-04T22:04:00',rA:{u6:4},rAdv:{u6:4},body:`Ik kijk naar het netto rendement van aflossen, dus na renteaftrek, en vergelijk dat met de rente op sparen na belasting. Daarnaast is liquiditeit belangrijk: houd een buffer aan voor onverwachte uitgaven en inkomensdaling. Aflossen boven de boetevrije ruimte kost een vergoeding. Ik bespreek ook of een lagere risicoklasse haalbaar is na aflossing. Leg de afweging en de gekozen buffer vast in het dossier.`}
  ]},
 {id:'vbd-044',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-09T08:15:00',views:439,tags:['rente','offerte','verlopen'],beste:null,
  titel:'Offerte verlopen: nieuwe offerte tegen hogere rente',
  body:`Door vertraging bij de notaris is de offerte van een klant verlopen. De nieuwe offerte heeft een hogere rente. Is er iets wat ik kan doen?`,
  antwoorden:[
   {id:'vbd-044-a1',auteur:'u4',datum:'2026-03-09T17:15:00',rA:{u1:4,u5:4,u8:4},rAdv:{u1:4,u5:4},body:`Een paar mogelijkheden:
- Vraag de geldverstrekker om verlenging van de offerte. Sommige geldverstrekkers staan dat toe, soms tegen een vergoeding of een renteaanpassing.
- Kijk of de geldverstrekker een rentedaalgarantie of renteafspraak heeft waarbij de laagste rente geldt.
- Vergelijk de nieuwe offerte met andere geldverstrekkers. Het kan zijn dat elders een lagere rente mogelijk is.
- Ga na waar de vertraging is ontstaan. Ligt die bij de notaris, dan kan dat een kwestie van aansprakelijkheid zijn.
Bespreek de gevolgen voor de maandlasten en controleer of de hypotheek nog binnen de leennormen past.
In het dossier leg ik vast hoe de vertraging is ontstaan, welke opties zijn onderzocht, wat de gevolgen zijn en welke keuze de klant heeft gemaakt. Ik leg ook vast wanneer ik de klant heb geïnformeerd, omdat dat punt bij een eventuele klacht van belang is.`}
  ]},
 {id:'vbd-045',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-12T13:45:00',views:254,tags:['verhuisregeling','gedeeltelijk','leningdelen'],beste:'vbd-045-a1',
  titel:'Verhuisregeling voor een deel van de leningdelen',
  body:`Een klant heeft drie leningdelen en wil alleen het deel met de laagste rente meenemen naar zijn nieuwe woning. De andere delen wil hij aflossen. Kan dat?`,
  antwoorden:[
   {id:'vbd-045-a1',auteur:'u1',datum:'2026-03-12T17:35:00',rA:{},rAdv:{},body:`Bij sommige geldverstrekkers kun je per leningdeel kiezen wat je meeneemt, bij anderen geldt de verhuisregeling voor de gehele lening. Controleer de voorwaarden van de geldverstrekker. Let ook op de vraag of het aflossen van de andere delen boetevrij is in combinatie met verkoop. Leg de keuze per leningdeel en de bijbehorende rente vast in het dossier.`},
   {id:'vbd-045-a2',auteur:'u4',datum:'2026-03-13T16:08:00',rA:{u5:4,u6:5,u3:3,u8:3},rAdv:{u3:3},body:`Ik heb het ook eens meegemaakt dat de geldverstrekker de gemeenschappelijke rente herberekende. Vraag daarom een schriftelijke bevestiging van de rente per leningdeel. Bewaar die bevestiging in het dossier.`}
  ]},
 {id:'vbd-046',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-16T09:20:00',views:157,tags:['aflosvorm','krediethypotheek','flexibel'],beste:null,
  titel:'Krediethypotheek als leningdeel: nog passend?',
  body:`Een klant met een bestaande krediethypotheek wil die behouden bij oversluiten. Bieden geldverstrekkers dit nog aan en wat zijn de aandachtspunten?`,
  antwoorden:[
   {id:'vbd-046-a1',auteur:'u5',datum:'2026-03-16T18:34:00',rA:{},rAdv:{},body:`Krediethypotheken worden door minder geldverstrekkers aangeboden. Bij oversluiten kan een bestaand kredietdeel soms worden omgezet naar aflossingsvrij of annuitair. Opgenomen bedragen voor de eigen woning en consumptief gebruik moeten fiscaal goed worden gescheiden. Controleer de voorwaarden van de nieuwe geldverstrekker. Leg de besteding en de fiscale behandeling vast in het dossier.`}
  ]},
 {id:'vbd-047',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-20T08:10:00',views:489,tags:['rente','LTV','verbouwing'],beste:null,
  titel:'Verbouwing waardoor de risicoklasse daalt: rente aanpassen?',
  body:`Een klant heeft verbouwd en de woningwaarde is daardoor gestegen. Kan hij na afloop een lagere risico-opslag krijgen en wanneer?`,
  antwoorden:[
   {id:'vbd-047-a1',auteur:'u4',datum:'2026-03-21T01:33:00',rA:{u8:4,u6:5},rAdv:{},body:`Ja, bij veel geldverstrekkers kan dat met een nieuwe waardebepaling na oplevering van de verbouwing. Sommigen herzien de risicoklasse automatisch als het bouwdepot is afgesloten en een taxatie op basis van verbouwde staat is aangeleverd. Controleer de voorwaarden. Leg de oude en nieuwe waarde en de aanvraag vast in het dossier.`}
  ]},
 {id:'vbd-048',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-23T11:45:00',views:381,tags:['oversluiten','termijn','planning'],beste:'vbd-048-a1',
  titel:'Hoe lang van tevoren beginnen met oversluiten?',
  body:`Een klant wil oversluiten maar vraagt hoeveel tijd het traject kost. Wat is een realistische planning vanaf het eerste gesprek tot het passeren bij de notaris?`,
  antwoorden:[
   {id:'vbd-048-a1',auteur:'u1',datum:'2026-03-24T04:35:00',rA:{u5:4,u2:4,u3:5},rAdv:{u5:4,u2:4,u3:5},body:`Reken voor het hele traject op enkele weken tot een paar maanden, afhankelijk van de snelheid van stukken, taxatie en de geldverstrekker. Belangrijke stappen:
- Opvragen van de vergoeding bij de huidige geldverstrekker.
- Taxatie of waardebepaling.
- Aanvraag, offerte en ondertekening.
- Afhandeling van de voorwaarden en passeren.
Plan ruim en houd rekening met de geldigheid van de offerte. Leg de planning vast in het dossier.`},
   {id:'vbd-048-a2',auteur:'u6',datum:'2026-03-24T20:36:00',rA:{u5:5,u3:5,u4:3},rAdv:{u5:5,u4:3},body:`In het CRM kun je een taakschema voor oversluiten maken met vaste termijnen. Dat helpt om niets te missen. Pas de termijnen wel aan per geldverstrekker. Het afvinken van taken geeft meteen een audit trail.`}
  ]},
 {id:'vbd-049',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-26T17:15:00',views:516,tags:['NHG','rente','risico-opslag'],beste:'vbd-049-a1',
  titel:'NHG of geen NHG bij een lage lening ten opzichte van waarde',
  body:`Een klant leent relatief weinig ten opzichte van de woningwaarde. Hij komt in aanmerking voor NHG maar de rente zonder NHG is in de laagste risicoklasse bijna gelijk. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbd-049-a1',auteur:'u5',datum:'2026-03-27T12:58:00',rA:{u4:5,u2:5},rAdv:{u2:5},body:`Vergelijk de rente met en zonder NHG en tel de borgtochtprovisie mee. Naast de rente biedt NHG een vangnet bij een restschuld na gedwongen verkoop onder voorwaarden. Die zekerheid weegt voor sommige klanten zwaar. Raadpleeg de actuele voorwaarden van NHG. Leg de vergelijking en de afweging van de klant vast in het dossier.`},
   {id:'vbd-049-a2',auteur:'u2',datum:'2026-03-28T08:28:00',rA:{},rAdv:{},body:`Bij een lage lening ten opzichte van de waarde is het restschuldrisico kleiner. Dan kan de rentevergelijking zwaarder wegen. Leg die afweging vast in het dossier.`}
  ]},
 {id:'vbd-050',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-03-30T14:50:00',views:452,tags:['rentevast','oversluiten','fiscaal'],beste:null,
  titel:'Renteaftrek na oversluiten met een kortere rentevaste periode',
  body:`Een klant wil oversluiten naar een kortere rentevaste periode omdat die rente nu lager is. Hij vraagt of dat invloed heeft op zijn renteaftrek. Wat zijn de aandachtspunten?`,
  antwoorden:[
   {id:'vbd-050-a1',auteur:'u5',datum:'2026-03-30T23:08:00',rA:{u3:3,u1:3,u8:5},rAdv:{u1:3},body:`De lengte van de rentevaste periode heeft op zich geen invloed op de renteaftrek, zolang de schuld een eigenwoningschuld blijft en aan de aflossingseis voldoet. Wel verandert de rente en daarmee het bedrag van de aftrek. Let bij oversluiten op de resterende fiscale looptijd en het overgangsrecht. Bij een korte rentevaste periode wordt bovendien met een toetsrente getoetst. Leg de fiscale toets en de keuze voor de rentevaste periode vast in het dossier.`},
   {id:'vbd-050-a2',auteur:'u2',datum:'2026-03-31T04:08:00',rA:{},rAdv:{},body:`Ik bespreek ook het renterisico na afloop van de korte periode. Een lagere rente nu weegt niet altijd op tegen onzekerheid later. Leg vast dat de klant dit risico bewust aanvaardt.`}
  ]},
 {id:'vbd-051',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-03T10:50:00',views:265,tags:['rentevast','renteverlenging','vergelijken'],beste:'vbd-051-a1',
  titel:'Renteverlenging bij huidige geldverstrekker of elders vergelijken?',
  body:`Bij renteverlenging tekenen veel klanten het voorstel van hun eigen geldverstrekker zonder te vergelijken. Hoe zetten jullie een renteverlengingstraject op en wat leggen jullie vast?`,
  antwoorden:[
   {id:'vbd-051-a1',auteur:'u4',datum:'2026-04-03T17:20:00',rA:{u1:5,u8:5,u7:3,u5:5},rAdv:{u8:5},body:`Ik vergelijk het renteverlengingsvoorstel met de actuele rentes van andere geldverstrekkers voor dezelfde risicoklasse. Bij een einde rentevaste periode is aflossen meestal boetevrij, dus oversluiten kost vooral notaris-, taxatie- en advieskosten. Ik toets daarnaast opnieuw de rentevaste periode aan de huidige situatie van de klant. Leg de vergelijking, de keuze en de motivering vast in het dossier.`},
   {id:'vbd-051-a2',auteur:'u1',datum:'2026-04-04T09:32:00',rA:{},rAdv:{},body:`Let op dat oversluiten wel een nieuwe acceptatietoets betekent. Als het inkomen is gedaald, kan blijven bij de huidige geldverstrekker de enige realistische optie zijn. Leg de uitkomst van de toets vast in het dossier.`}
  ]},
 {id:'vbd-052',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-07T13:10:00',views:54,tags:['aflossingsvrij','pensioen','betaalbaarheid'],beste:'vbd-052-a1',
  titel:'Aflossingsvrij deel bij pensionering: wat als de klant niet kan aflossen?',
  body:`Een klant heeft een aflossingsvrij deel dat na pensionering doorloopt. Hij vraagt of de geldverstrekker dan om aflossing vraagt. Hoe bereiden jullie dit voor?`,
  antwoorden:[
   {id:'vbd-052-a1',auteur:'u7',datum:'2026-04-07T15:36:00',rA:{},rAdv:{},body:`Een aflossingsvrij deel heeft vaak geen einddatum of een einddatum waarop de geldverstrekker het opnieuw beoordeelt. Controleer de voorwaarden van de geldverstrekker. Ik breng het pensioeninkomen in kaart en toets of de rentelasten op het aflossingsvrije deel betaalbaar blijven. Bespreek of geleidelijk aflossen voor de pensioendatum nodig is. Leg de prognose en de afspraken vast in het dossier.`},
   {id:'vbd-052-a2',auteur:'u2',datum:'2026-04-08T04:50:00',rA:{u8:5,u3:5},rAdv:{u8:5},body:`Ik maak ook een scenario voor het overlijden van een partner, omdat het inkomen dan verder kan dalen. Bespreek in dat geval ook de nabestaandenvoorzieningen. Leg het scenario vast in het dossier.`}
  ]},
 {id:'vbd-053',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-10T23:40:00',views:417,tags:['rente','opslag','aflossingsvrij'],beste:null,
  titel:'Renteopslag voor aflossingsvrij: hoe groot is die meestal?',
  body:`Een klant vraagt waarom het aflossingsvrije deel een hogere rente heeft dan het annuitaire deel. Is dat gebruikelijk?`,
  antwoorden:[
   {id:'vbd-053-a1',auteur:'u1',datum:'2026-04-11T12:45:00',rA:{u2:5},rAdv:{},body:`Ja, veel geldverstrekkers rekenen een opslag voor aflossingsvrije leningdelen, omdat de schuld niet daalt en het risico dus hoger blijft. De hoogte verschilt per geldverstrekker. Controleer de rentetabellen en voorwaarden. Leg de opslag en de afweging vast in het dossier.`}
  ]},
 {id:'vbd-054',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-14T12:05:00',views:588,tags:['verhuisregeling','rentemiddeling','combinatie'],beste:'vbd-054-a1',
  titel:'Na rentemiddeling verhuizen: welke rente neem je mee?',
  body:`Een klant heeft vorig jaar rentemiddeling gedaan en wil nu verhuizen. Neemt hij de gemiddelde rente mee of geldt de oorspronkelijke rente?`,
  antwoorden:[
   {id:'vbd-054-a1',auteur:'u4',datum:'2026-04-14T15:00:00',rA:{},rAdv:{},body:`Na rentemiddeling is de gemiddelde rente de nieuwe contractrente. Bij verhuizen neem je in principe die rente mee volgens de verhuisregeling, met de bijbehorende rentevaste periode. Controleer de voorwaarden van de geldverstrekker, want bij sommigen gelden aanvullende regels na rentemiddeling. Leg de contractrente en de meegenomen rente vast in het dossier.`}
  ]},
 {id:'vbd-055',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-18T08:40:00',views:497,tags:['rentewijziging','variabel','opzegging'],beste:'vbd-055-a1',
  titel:'Van variabele rente overstappen naar een vaste rente',
  body:`Een klant heeft variabele rente en wil nu een rentevaste periode afsluiten. Kan dat tussentijds en zijn daar kosten aan verbonden?`,
  antwoorden:[
   {id:'vbd-055-a1',auteur:'u1',datum:'2026-04-18T10:02:00',rA:{u4:3,u3:5,u6:5},rAdv:{u3:5,u6:5},body:`Overstappen van variabel naar vast kan bij de meeste geldverstrekkers tussentijds en zonder vergoeding, omdat er bij variabel geen nadeel voor de geldverstrekker is. Wel kunnen er administratiekosten zijn. Controleer de voorwaarden van de geldverstrekker. Ik bespreek opnieuw de gewenste rentevaste periode en de risicobereidheid. Leg de keuze vast in het dossier.`}
  ]},
 {id:'vbd-056',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-21T12:10:00',views:579,tags:['hypotheek','looptijd','einddatum'],beste:null,
  titel:'Hypotheek loopt af terwijl er nog schuld is',
  body:`Een klant heeft een hypotheekdeel met een einddatum in de komende jaren, maar er staat nog schuld open. Hoe gaan jullie hiermee om?`,
  antwoorden:[
   {id:'vbd-056-a1',auteur:'u5',datum:'2026-04-21T22:10:00',rA:{u1:4,u4:4,u2:5},rAdv:{u1:4,u4:4},body:`Begin op tijd: niet in het laatste jaar, maar ruim van tevoren. Dat is het belangrijkste. De opties:
- Aflossen uit vermogen of een bestaande polis.
- Het leningdeel verlengen of herfinancieren. Dat is een nieuw krediet met toetsing aan de leennormen, wat lastig kan zijn als het inkomen inmiddels lager is (bijvoorbeeld na pensionering). De Tijdelijke regeling hypothecair krediet laat de geldverstrekker wel ruimte om af te wijken bij oversluiten, als de klant in de woning blijft wonen en de nieuwe lening niet hoger is dan de af te lossen schuld plus de kosten van het oversluiten. Of een geldverstrekker die ruimte gebruikt, verschilt.
- Verkopen en kleiner wonen.
- Verzilveren met een andere constructie, zoals een verzilverhypotheek.
Let op de fiscale gevolgen: een herfinanciering kan het overgangsrecht beïnvloeden; controleer de regels. Neem ook contact op met de geldverstrekker. Veel geldverstrekkers benaderen klanten met een aflossingsvrij deel zelf, in lijn met de oproep van de AFM.
Gebruik restschuld-pensioen.html om de situatie bij de einddatum te laten zien.
In het dossier leg ik vast welke opties zijn besproken, welke keuze is gemaakt en wat er gebeurt als de klant niets doet.`}
  ]},
 {id:'vbd-057',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-25T11:10:00',views:210,tags:['rente','inkomensdaling','betalingsachterstand'],beste:'vbd-057-a1',
  titel:'Klant met betalingsproblemen wil lagere rente',
  body:`Een klant heeft door inkomensdaling betalingsproblemen. Hij vraagt of oversluiten naar een lagere rente kan helpen. Wat adviseren jullie?`,
  antwoorden:[
   {id:'vbd-057-a1',auteur:'u2',datum:'2026-04-26T09:53:00',rA:{u3:5,u5:5,u6:5,u4:3},rAdv:{u3:5,u5:5,u6:5},body:`Bij betalingsproblemen is oversluiten vaak moeilijk, omdat de nieuwe geldverstrekker opnieuw toetst. Ik adviseer vroegtijdig contact op te nemen met de huidige geldverstrekker. Die heeft vaak oplossingen, zoals tijdelijke aanpassing van de lasten of rentemiddeling. Breng het budget goed in kaart. Leg de situatie en de gesprekken vast in het dossier.`},
   {id:'vbd-057-a2',auteur:'u8',datum:'2026-04-26T23:31:00',rA:{u3:5,u6:5},rAdv:{},body:`Wees voorzichtig met advies in deze situatie. Een stap die de lasten op korte termijn verlaagt maar op lange termijn verhoogt, moet goed worden uitgelegd en vastgelegd. Leg in het dossier vast welke opties zijn besproken en waarom de klant koos.`}
  ]},
 {id:'vbd-058',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-04-28T23:15:00',views:164,tags:['lineair','aflosvorm','fiscaal'],beste:'vbd-058-a1',
  titel:'Lineair of annuitair: welke voldoet aan de fiscale aflossingseis?',
  body:`Een klant wil een nieuwe hypotheek en vraagt welke aflosvormen in aanmerking komen voor renteaftrek. Klopt het dat zowel lineair als annuitair voldoen?`,
  antwoorden:[
   {id:'vbd-058-a1',auteur:'u5',datum:'2026-04-29T11:02:00',rA:{u1:4},rAdv:{u1:4},body:`Ja. Voor nieuwe eigenwoningschulden moet de schuld ten minste annuitair worden afgelost binnen maximaal dertig jaar om recht te hebben op renteaftrek. Lineair aflossen gaat sneller dan annuitair en voldoet daarom ook. Er gelden aanvullende voorwaarden, en het overgangsrecht kan voor bestaande schulden anders uitpakken. Leg in het dossier vast welke aflosvorm is gekozen en de fiscale toets.`}
  ]},
 {id:'vbd-059',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-02T19:20:00',views:55,tags:['hybride','aflosvorm','combinatie'],beste:null,
  titel:'Combinatie van annuitair en aflossingsvrij: hoe motiveren jullie de verdeling?',
  body:`Een klant wil de maandlast drukken met een aflossingsvrij deel naast een annuitair deel. Hoe bepalen jullie een verantwoorde verdeling?`,
  antwoorden:[
   {id:'vbd-059-a1',auteur:'u2',datum:'2026-05-03T09:11:00',rA:{},rAdv:{},body:`Ik kijk naar de lasten nu en na pensionering, de schuld op pensioendatum en het vermogen van de klant. Een verantwoorde verdeling past binnen de acceptatienormen en houdt de restschuld beheersbaar. Toets of de klant het aflossingsvrije deel later kan aflossen of dragen. Raadpleeg de actuele normen. Leg de verdeling en de motivering vast in het dossier.`},
   {id:'vbd-059-a2',auteur:'u5',datum:'2026-05-03T17:24:00',rA:{u2:5,u6:5},rAdv:{},body:`Fiscaal: het aflossingsvrije deel valt in box 3 als het geen overgangsrecht heeft. Neem dit mee in de netto lasten. Leg de netto lasten per leningdeel vast in het dossier.`}
  ]},
 {id:'vbd-060',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-06T21:20:00',views:287,tags:['oversluiten','aftrek','vergoeding'],beste:'vbd-060-a1',
  titel:'Is de vergoeding bij oversluiten aftrekbaar?',
  body:`Een klant betaalt een vergoeding wegens vervroegde aflossing bij oversluiten. Hij vraagt of die aftrekbaar is. Wat zijn de voorwaarden?`,
  antwoorden:[
   {id:'vbd-060-a1',auteur:'u5',datum:'2026-05-07T07:24:00',rA:{u4:3,u1:3},rAdv:{},body:`Een vergoeding bij oversluiten van een eigenwoningschuld kan onder voorwaarden aftrekbaar zijn als kosten van geldlening. Er zijn belangrijke voorwaarden, bijvoorbeeld dat de schuld wordt overgesloten en niet wordt afgelost bij verkoop. Bij meefinancieren van de vergoeding gelden aparte regels. Laat de fiscale behandeling toetsen. Leg de toets vast in het dossier.`},
   {id:'vbd-060-a2',auteur:'u2',datum:'2026-05-07T08:54:00',rA:{u6:3,u7:5},rAdv:{},body:`Ik noem bij de klant altijd dat dit afhankelijk is van zijn persoonlijke situatie en verwijs naar de actuele fiscale regels. Zo voorkom je dat de klant het als garantie opvat. Leg de toets en de verwijzing vast in het dossier.`}
  ]},
 {id:'vbd-061',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-10T11:30:00',views:220,tags:['rente','maandlasten','overzicht'],beste:'vbd-061-a1',
  titel:'Hoe presenteren jullie de netto maandlasten bij verschillende rentes?',
  body:`Klanten verliezen het overzicht bij veel rentescenario's. Hoe presenteren jullie de netto maandlasten overzichtelijk?`,
  antwoorden:[
   {id:'vbd-061-a1',auteur:'u6',datum:'2026-05-10T19:57:00',rA:{},rAdv:{},body:`Ik gebruik een tabel met de rentevaste periodes in kolommen en de bruto en netto maandlasten in rijen, plus een scenario met een hogere rente. In ons adviespakket kan dat als standaardrapport worden gegenereerd. Houd het bij drie tot vier opties. Sla het overzicht op als bijlage bij het advies in het dossier.`},
   {id:'vbd-061-a2',auteur:'u1',datum:'2026-05-10T20:37:00',rA:{u8:5},rAdv:{u8:5},body:`Ik laat altijd ook de bruto maandlast zien, omdat de renteaftrek in de toekomst kan veranderen. Zo ziet de klant ook wat hij betaalt als de aftrek lager uitvalt. Neem beide bedragen op in het rapport.`}
  ]},
 {id:'vbd-062',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-14T08:15:00',views:102,tags:['verhuisregeling','overlijden','partner'],beste:null,
  titel:'Rente meenemen na overlijden van de partner',
  body:`Na overlijden van een partner wil de achterblijvende partner verhuizen naar een kleinere woning. Kan de verhuisregeling hier ook worden gebruikt?`,
  antwoorden:[
   {id:'vbd-062-a1',auteur:'u1',datum:'2026-05-15T06:34:00',rA:{u5:5,u2:4},rAdv:{u2:4},body:`Dat hangt af van de voorwaarden van de geldverstrekker. Bij overlijden is aflossing vaak boetevrij, en de verhuisregeling kan ook gelden als de achterblijvende partner zelfstandig de lasten kan dragen. Er volgt in de regel een nieuwe toets. Controleer de voorwaarden. Leg de gesprekken en de toetsing zorgvuldig vast in het dossier.`}
  ]},
 {id:'vbd-063',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-17T13:25:00',views:523,tags:['rente','bijleenregeling','verhoging'],beste:'vbd-063-a1',
  titel:'Verhoging bij verbouwing: welke rente en welke fiscale behandeling?',
  body:`Een klant verhoogt zijn hypotheek voor een verbouwing. Hoe zorgen jullie dat het extra deel fiscaal goed wordt behandeld en dat de rente klopt?`,
  antwoorden:[
   {id:'vbd-063-a1',auteur:'u5',datum:'2026-05-17T19:28:00',rA:{u7:4},rAdv:{u7:4},body:`Het extra deel is aftrekbaar als het wordt besteed aan verbetering of onderhoud van de eigen woning en aan de aflossingseis voldoet. Laat de klant facturen bewaren als onderbouwing. Toets ook de bijleenregeling. Het extra deel krijgt meestal de actuele rente. Leg de bestedingen en de fiscale toets vast in het dossier.`}
  ]},
 {id:'vbd-064',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-20T21:35:00',views:124,tags:['rentevast','starter','zekerheid'],beste:'vbd-064-a1',
  titel:'Starter wil korte rentevaste periode vanwege verwachte verhuizing',
  body:`Een starter verwacht over enkele jaren te verhuizen en wil daarom een korte rentevaste periode. Is dat verstandig gezien de verhuisregeling?`,
  antwoorden:[
   {id:'vbd-064-a1',auteur:'u4',datum:'2026-05-21T06:29:00',rA:{},rAdv:{},body:`Met een verhuisregeling kan een langere rentevaste periode vaak worden meegenomen naar de volgende woning, waardoor het argument voor een korte periode zwakker wordt. Bij een korte rentevaste periode geldt bovendien de toetsrente, wat de leencapaciteit kan beperken. Controleer de voorwaarden van de verhuisregeling. Leg de afweging vast in het dossier.`},
   {id:'vbd-064-a2',auteur:'u1',datum:'2026-05-21T08:39:00',rA:{u3:4,u6:5},rAdv:{u3:4},body:`Wijs de klant er ook op dat verhuisplannen kunnen veranderen. Een rentevaste periode moet ook passen als hij langer blijft. Leg die afweging vast in het dossier.`}
  ]},
 {id:'vbd-065',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-24T22:35:00',views:281,tags:['rentemiddeling','kosten','transparantie'],beste:null,
  titel:'Hoe controleer je de opslag bij rentemiddeling?',
  body:`Een geldverstrekker biedt rentemiddeling aan met een opslag. Hoe controleren jullie of die opslag redelijk is?`,
  antwoorden:[
   {id:'vbd-065-a1',auteur:'u1',datum:'2026-05-25T10:35:00',rA:{u4:4,u5:5,u2:4},rAdv:{u4:4,u5:5},body:`Bij rentemiddeling wordt de boeterente verwerkt in een nieuwe rente. De opslag is het deel bovenop de actuele rente. Zo controleer ik dat:
- Vraag de geldverstrekker om een specificatie: de huidige rente, de nieuwe rente, de opslag en de berekening van de boeterente.
- Controleer de boeteberekening: de contante waarde van het renteverschil over de resterende looptijd, de gebruikte vergelijkingsrente en de vergoedingsvrije ruimte.
- Vergelijk de gemiddelde rente met de actuele rente plus opslag.
- Vergelijk met oversluiten en de boete ineens betalen.
Gebruik rentemiddeling.html om de varianten naast elkaar te zetten. Een opslag die hoger is dan nodig om de boete te dekken, is een verborgen kostenpost.
In het dossier leg ik vast welke specificatie is ontvangen, hoe de varianten zijn vergeleken en waarom de klant kiest. Bij twijfel over de berekening vraag ik de geldverstrekker om een toelichting en leg ik het antwoord vast.`}
  ]},
 {id:'vbd-066',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-05-28T12:10:00',views:267,tags:['oversluiten','NHG','kostengrens'],beste:'vbd-066-a1',
  titel:'Oversluiten met NHG naar een andere geldverstrekker',
  body:`Een klant met NHG wil oversluiten. Kan de NHG worden overgedragen naar een nieuwe geldverstrekker of moet die opnieuw worden aangevraagd?`,
  antwoorden:[
   {id:'vbd-066-a1',auteur:'u5',datum:'2026-05-29T08:50:00',rA:{u4:4,u3:5,u1:4,u6:5},rAdv:{u1:4,u6:5},body:`Bij oversluiten wordt NHG opnieuw aangevraagd bij de nieuwe geldverstrekker. Er gelden voorwaarden, zoals de kostengrens en het doel van de lening. De borgtochtprovisie is opnieuw verschuldigd. Raadpleeg de actuele NHG-voorwaarden. Leg de toets vast in het dossier.`}
  ]},
 {id:'vbd-067',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-01T16:20:00',views:182,tags:['rente','partner','hoofdelijk'],beste:null,
  titel:'Rente-aanbod bij het toevoegen van een nieuwe partner',
  body:`Een klant gaat samenwonen en de nieuwe partner wordt medeschuldenaar. Blijft de bestaande rente staan of wordt het een nieuwe hypotheek?`,
  antwoorden:[
   {id:'vbd-067-a1',auteur:'u1',datum:'2026-06-02T12:09:00',rA:{u6:5,u2:5},rAdv:{},body:`Het toevoegen van een partner als hoofdelijk schuldenaar kan bij veel geldverstrekkers zonder nieuwe hypotheek, met behoud van de rente. Er volgt wel een toetsing en vaak een notariele akte. Controleer de voorwaarden. Leg de toetsing en de afspraken vast in het dossier.`},
   {id:'vbd-067-a2',auteur:'u5',datum:'2026-06-02T18:42:00',rA:{u6:3},rAdv:{},body:`Let op de fiscale kant van het mede-eigendom en de bijleenregeling. Bespreek ook een samenlevingscontract. Leg vast dat deze punten zijn besproken.`}
  ]},
 {id:'vbd-068',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-05T08:15:00',views:211,tags:['aflosvorm','spaarhypotheek','premievrij'],beste:'vbd-068-a1',
  titel:'Spaarhypotheek premievrij maken: gevolgen voor rente?',
  body:`Een klant wil zijn spaarhypotheek premievrij maken om lasten te verlagen. Heeft dat gevolgen voor de rente of de hypotheek?`,
  antwoorden:[
   {id:'vbd-068-a1',auteur:'u3',datum:'2026-06-05T17:00:00',rA:{u6:4},rAdv:{u6:4},body:`Premievrij maken verlaagt het eindkapitaal van de spaarverzekering. De koppeling met de hypotheekrente blijft vaak bestaan, maar de dekking op einddatum valt lager uit. Controleer de voorwaarden van de verzekeraar en geldverstrekker. Fiscaal kan het gevolgen hebben; laat dat toetsen. Leg de gevolgen vast in het dossier.`}
  ]},
 {id:'vbd-069',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-08T09:35:00',views:26,tags:['rente','onderpand','verhuur'],beste:'vbd-069-a1',
  titel:'Rente bij het verhuren van de eigen woning',
  body:`Een klant wil zijn woning tijdelijk verhuren omdat hij voor werk naar het buitenland gaat. Heeft dat gevolgen voor de rente en de hypotheek?`,
  antwoorden:[
   {id:'vbd-069-a1',auteur:'u1',datum:'2026-06-08T20:54:00',rA:{},rAdv:{},body:`Verhuren zonder toestemming van de geldverstrekker is meestal niet toegestaan. Sommige geldverstrekkers geven toestemming voor tijdelijke verhuur, soms met een renteopslag. Controleer de voorwaarden. Fiscaal kan de woning tijdelijk geen eigen woning meer zijn. Leg de toestemming en de fiscale toets vast in het dossier.`},
   {id:'vbd-069-a2',auteur:'u5',datum:'2026-06-09T04:04:00',rA:{u2:5,u4:5},rAdv:{},body:`Fiscaal is er een uitzondering bij tijdelijke uitzending, onder voorwaarden. Laat dit toetsen. Leg de duur van de uitzending en de toets vast in het dossier.`}
  ]},
 {id:'vbd-070',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-12T14:05:00',views:406,tags:['rentevast','afloopdatum','herinnering'],beste:'vbd-070-a1',
  titel:'Klanten tijdig attenderen op het einde van de rentevaste periode',
  body:`Hoe zorgen jullie dat klanten tijdig worden benaderd voor het einde van de rentevaste periode? Ik merk dat ik soms te laat ben.`,
  antwoorden:[
   {id:'vbd-070-a1',auteur:'u6',datum:'2026-06-13T09:03:00',rA:{u2:4,u8:4},rAdv:{},body:`In ons CRM staat de einddatum van de rentevaste periode als veld bij elk leningdeel. Ik heb een signaal ingesteld dat een aantal maanden ervoor een taak aanmaakt. Zo kun je tijdig een vergelijkingsgesprek inplannen. Leg in het dossier vast wanneer de klant is benaderd.`},
   {id:'vbd-070-a2',auteur:'u8',datum:'2026-06-14T06:18:00',rA:{u1:5,u7:4,u2:4,u3:4},rAdv:{u7:4},body:`Vanuit compliance: als je een doorlopende dienstverleningsrelatie hebt, ligt het voor de hand dat je klanten tijdig informeert. Leg de afspraken over nazorg vast. Leg die afspraken vast in de dienstverleningsdocumenten.`}
  ]},
 {id:'vbd-071',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-15T18:55:00',views:320,tags:['rente','verhuisregeling','nieuwe geldverstrekker'],beste:null,
  titel:'Verhuisregeling werkt niet bij overstap naar andere geldverstrekker',
  body:`Een klant verhuist en wil de hypotheek onderbrengen bij een andere geldverstrekker vanwege betere voorwaarden. Kan hij dan nog gebruik maken van de verhuisregeling van zijn oude geldverstrekker?`,
  antwoorden:[
   {id:'vbd-071-a1',auteur:'u4',datum:'2026-06-16T14:42:00',rA:{u3:4},rAdv:{u3:4},body:`Nee, de verhuisregeling geldt alleen bij dezelfde geldverstrekker. Bij een overstap wordt de oude hypotheek afgelost. Bij verkoop is dat vaak boetevrij, maar controleer de voorwaarden. De nieuwe geldverstrekker rekent de actuele rente. Leg de vergelijking tussen meenemen en overstappen vast in het dossier.`}
  ]},
 {id:'vbd-072',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-19T09:55:00',views:263,tags:['rente','familiehypotheek','lening'],beste:'vbd-072-a1',
  titel:'Familielening naast een gewone hypotheek: welke rente?',
  body:`Ouders willen een deel van de financiering verstrekken als lening. Welke rente is gebruikelijk en hoe leggen jullie dat vast?`,
  antwoorden:[
   {id:'vbd-072-a1',auteur:'u5',datum:'2026-06-19T16:35:00',rA:{},rAdv:{},body:`Voor de fiscale aftrek moet de rente zakelijk zijn, vergelijkbaar met wat een geldverstrekker zou rekenen voor een vergelijkbare lening. Leg de lening vast in een schriftelijke overeenkomst, eventueel notarieel. Fiscaal gelden de normale aflossingseisen. Controleer ook de acceptatievoorwaarden van de geldverstrekker voor de familielening. Leg de overeenkomst en de toets vast in het dossier.`},
   {id:'vbd-072-a2',auteur:'u2',datum:'2026-06-20T11:40:00',rA:{},rAdv:{},body:`Bij de ouders speelt de vordering in box 3. Breng dat ook in kaart. Leg dit vast in het dossier van beide partijen als je hen allebei adviseert.`}
  ]},
 {id:'vbd-073',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-23T17:45:00',views:6,tags:['bouwdepot','verlenging','rente'],beste:'vbd-073-a1',
  titel:'Bouwdepot verlengen: gevolgen voor rente en kosten',
  body:`De verbouwing van een klant loopt uit en het bouwdepot dreigt af te lopen. Kan het depot worden verlengd en wat zijn de gevolgen?`,
  antwoorden:[
   {id:'vbd-073-a1',auteur:'u4',datum:'2026-06-24T16:33:00',rA:{u3:3},rAdv:{u3:3},body:`Veel geldverstrekkers staan verlenging van het bouwdepot toe op aanvraag, soms met kosten of met een andere depotvergoeding. Bij afloop wordt het saldo anders vaak afgeboekt op de lening. Controleer de voorwaarden. Leg de aanvraag en de afspraken vast in het dossier.`}
  ]},
 {id:'vbd-074',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-27T08:40:00',views:87,tags:['oversluiten','inkomen','acceptatie'],beste:'vbd-074-a1',
  titel:'Oversluiten met een lager inkomen dan bij aanvang',
  body:`Een klant wil oversluiten naar een lagere rente, maar zijn inkomen is sinds de aanvang gedaald. Kan dat nog?`,
  antwoorden:[
   {id:'vbd-074-a1',auteur:'u1',datum:'2026-06-28T01:17:00',rA:{u4:5,u3:4,u5:3,u2:5},rAdv:{u3:4,u2:5},body:`Oversluiten betekent een nieuwe toets op inkomen. Als de lening niet past bij het huidige inkomen, kan oversluiten lastig zijn. Sommige geldverstrekkers hanteren regels voor oversluiten zonder verhoging waarbij afwijken van de normen onder voorwaarden is toegestaan. Raadpleeg de actuele normen en de voorwaarden. Leg de toetsing vast in het dossier.`},
   {id:'vbd-074-a2',auteur:'u4',datum:'2026-06-28T13:29:00',rA:{u8:4,u5:5,u3:5,u7:5},rAdv:{u5:5,u3:5,u7:5},body:`Alternatief: rentemiddeling bij de huidige geldverstrekker, waarbij geen nieuwe inkomenstoets nodig is. Wel kost dat vaak een opslag in de rente. Vergelijk beide routes en leg de keuze vast in het dossier.`}
  ]},
 {id:'vbd-075',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-06-30T14:40:00',views:175,tags:['rente','percentage','kortingen'],beste:null,
  titel:'Kortingen stapelen: betaalrekening en energielabel',
  body:`Sommige geldverstrekkers bieden een rentekorting bij een betaalrekening of een duurzaamheidslabel. Hoe nemen jullie dat mee in de vergelijking?`,
  antwoorden:[
   {id:'vbd-075-a1',auteur:'u4',datum:'2026-07-01T11:22:00',rA:{u3:5,u2:3},rAdv:{u3:5,u2:3},body:`Ik neem kortingen mee in de vergelijking, maar wijs de klant op de voorwaarden. Een korting voor een betaalrekening vervalt vaak als de rekening wordt opgezegd. Controleer de voorwaarden van de geldverstrekker. Leg de toegepaste kortingen en voorwaarden vast in het dossier.`}
  ]},
 {id:'vbd-076',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-04T12:30:00',views:351,tags:['rentevast','lange periode','vergoeding'],beste:'vbd-076-a1',
  titel:'Rentevaste periode van twintig of dertig jaar: risico bij tussentijds aflossen',
  body:`Een klant wil de rente voor de hele looptijd vastzetten. Ik wil hem wijzen op de risico's bij tussentijds aflossen. Welke punten bespreken jullie?`,
  antwoorden:[
   {id:'vbd-076-a1',auteur:'u4',datum:'2026-07-05T08:58:00',rA:{u8:5},rAdv:{u8:5},body:`Bij een lange rentevaste periode kan de vergoeding bij tussentijds aflossen boven de boetevrije ruimte flink oplopen als de rente daalt. Bij verkoop van de woning is aflossing vaak boetevrij en met een verhuisregeling kan de rente mee, maar bij oversluiten of herfinanciering speelt de vergoeding wel. Sommige geldverstrekkers rekenen na een bepaald aantal jaren de vergoeding anders; controleer de voorwaarden. Ik leg in het dossier vast dat de klant de risico's begrijpt en waarom hij voor zekerheid kiest.`},
   {id:'vbd-076-a2',auteur:'u2',datum:'2026-07-05T15:57:00',rA:{u3:4,u5:5,u4:5},rAdv:{u3:4,u5:5,u4:5},body:`Ik laat de klant ook zien hoeveel hij meer betaalt voor de langste periode ten opzichte van een middellange periode. Zo kan hij de prijs van zekerheid zelf afwegen. Die vergelijking neem ik op als bijlage in het dossier.`}
  ]},
 {id:'vbd-077',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-07T20:50:00',views:436,tags:['verhuisregeling','duurdere woning','rente middelen'],beste:null,
  titel:'Gemiddelde rente na meenemen en bijlenen: hoe wordt die berekend?',
  body:`Een geldverstrekker berekent bij verhuizen een gemiddelde rente over het meegenomen en het nieuwe deel. Hoe werkt die berekening en waar moet ik op letten?`,
  antwoorden:[
   {id:'vbd-077-a1',auteur:'u1',datum:'2026-07-08T16:40:00',rA:{u2:5},rAdv:{},body:`Bij een gemiddelde rente wordt de rente van het meegenomen deel en de actuele rente van het nieuwe deel gewogen naar bedrag en soms naar resterende rentevaste periode. Het resultaat geldt dan voor de gehele lening. Vraag de berekening schriftelijk op en vergelijk die met gescheiden leningdelen bij een andere aanpak. Controleer de voorwaarden van de geldverstrekker. Leg de berekening en de uitkomst vast in het dossier.`}
  ]},
 {id:'vbd-078',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-12T10:00:00',views:10,tags:['aflosvorm','lineair','pensioen'],beste:'vbd-078-a1',
  titel:'Lineair aflossen om voor pensionering schuldenvrij te zijn',
  body:`Een klant van rond de vijftig wil schuldenvrij zijn voor zijn pensioen. Hij overweegt lineair met een kortere looptijd. Hoe toetsen jullie dit?`,
  antwoorden:[
   {id:'vbd-078-a1',auteur:'u7',datum:'2026-07-13T08:14:00',rA:{u8:4},rAdv:{u8:4},body:`Ik zet de looptijd af tegen de pensioendatum en reken de aanvangslasten van lineair met de kortere looptijd door. Die lasten liggen in het begin hoog, dus toets of ze passen bij het huidige inkomen en of er nog buffer overblijft. Een alternatief is annuitair met extra aflossen binnen de boetevrije ruimte. Leg de berekening en de gekozen route vast in het dossier.`},
   {id:'vbd-078-a2',auteur:'u2',datum:'2026-07-13T13:54:00',rA:{},rAdv:{},body:`Kijk ook naar het effect op pensioenopbouw en vermogen. Soms is extra pensioensparen fiscaal aantrekkelijker dan versneld aflossen. Maak beide routes inzichtelijk voor de klant.`}
  ]},
 {id:'vbd-079',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-15T19:15:00',views:464,tags:['rentemiddeling','opslag','vergelijking'],beste:null,
  titel:'Rentemiddeling aangeboden met een rente hoger dan verwacht',
  body:`Een klant kreeg een rentemiddelingsvoorstel met een rente hoger dan we hadden ingeschat. Hoe controleren jullie of de berekening klopt?`,
  antwoorden:[
   {id:'vbd-079-a1',auteur:'u4',datum:'2026-07-16T06:15:00',rA:{u1:4,u5:4,u2:4},rAdv:{u1:4,u5:4},body:`Een hogere rente dan verwacht zit vaak in de details. Zo controleer ik:
- Specificatie: welke boeterente, welke opslag, welke rente zonder middeling.
- Boeteberekening: is de vergoedingsvrije ruimte meegenomen? Welke vergelijkingsrente is gebruikt? Is de juiste resterende rentevaste periode gebruikt?
- Risicoklasse: is de woningwaarde actueel? Een verouderde waarde kan tot een hogere risicoklasse leiden.
- Rentevaste periode: is dezelfde periode vergeleken?
Als iets niet klopt, vraag de geldverstrekker om een herberekening. Met rentemiddeling.html kun je de varianten vergelijken.
In het dossier leg ik vast welke gegevens zijn gebruikt, welke vragen zijn gesteld en welke conclusie is getrokken. Als de klant toch voor rentemiddeling kiest, leg ik vast dat hij de alternatieven kent.`}
  ]},
 {id:'vbd-080',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-19T07:15:00',views:438,tags:['oversluiten','aflossingsvrij','box 3'],beste:'vbd-080-a1',
  titel:'Box 3-deel bij oversluiten apart houden',
  body:`Een klant heeft een leningdeel dat fiscaal in box 3 valt naast een eigenwoningschuld. Hoe zorgen jullie bij oversluiten dat de delen goed gescheiden blijven?`,
  antwoorden:[
   {id:'vbd-080-a1',auteur:'u5',datum:'2026-07-20T06:04:00',rA:{u3:4,u6:5,u4:5},rAdv:{u3:4,u6:5},body:`Ik laat de leningdelen bij de nieuwe geldverstrekker apart opnemen, zodat de eigenwoningschuld en het box 3-deel zichtbaar gescheiden blijven. Bij gedeeltelijke aflossing kan de klant soms kiezen welk deel wordt afgelost; dat heeft fiscaal effect. Controleer de mogelijkheden bij de geldverstrekker. Leg de opbouw per leningdeel en de fiscale kwalificatie vast in het dossier.`},
   {id:'vbd-080-a2',auteur:'u6',datum:'2026-07-20T08:25:00',rA:{u4:5},rAdv:{},body:`In het adviespakket kun je per leningdeel het fiscale regime vastleggen. Dat voorkomt dat het bij een volgende wijziging door elkaar loopt. Controleer na import of de gegevens goed zijn overgenomen.`}
  ]},
 {id:'vbd-081',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-22T18:45:00',views:149,tags:['renteverlenging','tussentijds','nieuwe rente'],beste:'vbd-081-a1',
  titel:'Tussentijds een nieuwe rentevaste periode vastzetten',
  body:`Een klant wil zijn huidige rentevaste periode tussentijds verlengen, omdat hij een stijging verwacht. Is dat mogelijk zonder vergoeding?`,
  antwoorden:[
   {id:'vbd-081-a1',auteur:'u4',datum:'2026-07-23T04:59:00',rA:{u2:4,u3:3},rAdv:{u2:4},body:`Tussentijds verlengen gaat meestal via rentemiddeling of via een vervroegde renteverlenging. Bij rentemiddeling wordt de vergoeding verwerkt in de rente. Sommige geldverstrekkers bieden een periode voor de einddatum waarin je zonder vergoeding de nieuwe rente kunt vastleggen. Controleer de voorwaarden. Leg de keuze en de berekening vast in het dossier.`},
   {id:'vbd-081-a2',auteur:'u1',datum:'2026-07-23T21:53:00',rA:{u5:5},rAdv:{},body:`Wijs de klant er ook op dat ook adviseurs de rente niet kunnen voorspellen. Het doel is zekerheid, niet speculeren. Dat noteer ik ook expliciet in het advies.`}
  ]},
 {id:'vbd-082',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-26T09:50:00',views:507,tags:['rente','dossier','renteaanbod'],beste:null,
  titel:'Welke versie van het rente-aanbod bewaren in het dossier?',
  body:`Bij een aanvraag krijgen we vaak meerdere renteaanbiedingen en offertes. Welke stukken bewaren jullie en hoe zorgen jullie dat het dossier overzichtelijk blijft?`,
  antwoorden:[
   {id:'vbd-082-a1',auteur:'u8',datum:'2026-07-26T20:05:00',rA:{u7:3,u2:5,u6:5,u5:5},rAdv:{u2:5,u6:5,u5:5},body:`Bewaar ten minste de rentevergelijking waarop het advies is gebaseerd, de getekende offerte en eventuele gewijzigde offertes. Leg bij elke wijziging vast waarom de offerte is aangepast. Zo is de route navolgbaar. Ik raad aan om oudere versies niet te verwijderen maar te markeren als vervallen.`},
   {id:'vbd-082-a2',auteur:'u6',datum:'2026-07-27T06:03:00',rA:{u2:5,u8:5,u7:4},rAdv:{u7:4},body:`In het dossier kun je documenttypes gebruiken zoals offerte, gewijzigde offerte en rentevergelijking. Dan is in één oogopslag te zien welke versie geldig is. Zet de datum ook in de bestandsnaam.`}
  ]},
 {id:'vbd-083',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-07-30T07:30:00',views:327,tags:['verhuisregeling','huurwoning','verkoop'],beste:'vbd-083-a1',
  titel:'Verhuisregeling bij verkoop zonder nieuwe koopwoning',
  body:`Een klant verkoopt zijn woning en gaat definitief huren. Moet hij een vergoeding betalen voor het aflossen van zijn hypotheek?`,
  antwoorden:[
   {id:'vbd-083-a1',auteur:'u1',datum:'2026-07-30T09:46:00',rA:{u8:5,u7:4,u6:3,u3:5},rAdv:{u7:4},body:`Bij verkoop van de woning is aflossen bij de meeste geldverstrekkers boetevrij, ook als er geen nieuwe woning wordt gekocht. Controleer de voorwaarden van de geldverstrekker, want er zijn uitzonderingen, bijvoorbeeld bij verkoop aan een familielid. Leg de verkoopovereenkomst en de bevestiging van de geldverstrekker vast in het dossier.`}
  ]},
 {id:'vbd-084',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-02T17:45:00',views:102,tags:['rente','opslag','scheiding'],beste:'vbd-084-a1',
  titel:'Renteopslag na ontslag hoofdelijke aansprakelijkheid',
  body:`Na een scheiding neemt een partner de hypotheek over. De geldverstrekker berekent een nieuwe risicoklasse. Kan dat tot een hogere rente leiden?`,
  antwoorden:[
   {id:'vbd-084-a1',auteur:'u4',datum:'2026-08-02T21:37:00',rA:{u7:5,u6:5},rAdv:{u7:5,u6:5},body:`Ja, als door de overname de verhouding lening tot waarde verandert of een andere aflosvorm wordt gekozen, kan de risico-opslag wijzigen. Bij een verhoging om de ex-partner uit te kopen stijgt de lening vaak ten opzichte van de waarde. Controleer de voorwaarden van de geldverstrekker. Leg de nieuwe rente en de berekening vast in het dossier.`}
  ]},
 {id:'vbd-085',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-06T19:20:00',views:49,tags:['oversluiten','overgangsrecht','fiscaal'],beste:'vbd-085-a1',
  titel:'Overgangsrecht verliezen door verhoging bij oversluiten',
  body:`Een klant wil oversluiten met een kleine verhoging. Zijn bestaande lening valt onder het overgangsrecht. Verliest hij dat voor de hele lening?`,
  antwoorden:[
   {id:'vbd-085-a1',auteur:'u5',datum:'2026-08-07T13:04:00',rA:{},rAdv:{},body:`Nee, het overgangsrecht geldt voor de bestaande schuld. Het extra deel valt onder de huidige regels en moet ten minste annuitair worden afgelost voor renteaftrek. Het is belangrijk dat de delen goed gescheiden blijven. Laat de fiscale toets goed doen. Leg de opbouw per leningdeel vast in het dossier.`},
   {id:'vbd-085-a2',auteur:'u2',datum:'2026-08-07T19:07:00',rA:{u1:4,u8:5,u6:4,u5:5},rAdv:{u1:4,u6:4,u5:5},body:`In de praktijk adviseer ik de verhoging als apart leningdeel op te nemen. Dat maakt de administratie en de aangifte eenvoudiger. Leg ook vast welk deel onder welk regime valt.`}
  ]},
 {id:'vbd-086',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-09T21:25:00',views:525,tags:['rentekeuze','risicoprofiel','vragenlijst'],beste:'vbd-086-a1',
  titel:'Risicobereidheid rente meten: gebruiken jullie een vragenlijst?',
  body:`Hoe stellen jullie de risicobereidheid van een klant vast voor de keuze van de rentevaste periode? Werken jullie met een vragenlijst of in gesprek?`,
  antwoorden:[
   {id:'vbd-086-a1',auteur:'u8',datum:'2026-08-09T23:04:00',rA:{u7:3,u4:3},rAdv:{u7:3},body:`Een vragenlijst helpt om de risicobereidheid gestructureerd en navolgbaar vast te leggen. Combineer die met een gesprek, omdat klanten vragen soms anders interpreteren. Vraag ook naar de financiele ruimte bij een lastenstijging. Leg zowel de uitkomst als de toelichting vast in het dossier.`},
   {id:'vbd-086-a2',auteur:'u6',datum:'2026-08-10T13:01:00',rA:{u2:3},rAdv:{u2:3},body:`Ons adviespakket heeft een module voor risicobereidheid met vaste vragen. De uitkomst komt automatisch in het adviesrapport. Je kunt per vraag een toelichting toevoegen.`}
  ]},
 {id:'vbd-087',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-14T10:15:00',views:382,tags:['rente','annuiteit','aflossingsschema'],beste:null,
  titel:'Klant snapt het annuitaire aflossingsschema niet',
  body:`Een klant vraagt waarom hij in het begin weinig aflost en vooral rente betaalt bij een annuitaire hypotheek. Hoe leggen jullie dit eenvoudig uit?`,
  antwoorden:[
   {id:'vbd-087-a1',auteur:'u1',datum:'2026-08-14T20:15:00',rA:{u4:4,u5:5,u3:4},rAdv:{u4:4,u5:5},body:`Ik leg het zo uit: bij een annuïtaire hypotheek betaal je elke maand hetzelfde bruto bedrag. Dat bedrag bestaat uit rente en aflossing. De rente wordt berekend over de schuld die nog openstaat. In het begin is die schuld hoog, dus is de rente hoog en blijft er weinig over voor aflossing. Elke maand wordt de schuld een beetje lager, dus de rente ook. Daardoor gaat er elk jaar meer naar aflossing.
Wat helpt:
- Laat een aflossingsschema zien met het verloop van rente en aflossing per jaar.
- Laat zien dat de netto lasten door de dalende renteaftrek in de loop van de tijd stijgen.
- Laat met extra-aflossen.html zien wat extra aflossen doet.
- Vergelijk met lineair: hogere lasten in het begin, sneller lagere schuld.
In het dossier leg ik vast dat de aflossingsvorm is uitgelegd en dat de klant het verloop van de netto lasten begrijpt.`}
  ]},
 {id:'vbd-088',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-17T19:10:00',views:537,tags:['rente','verbouwingsdepot','extra aflossen'],beste:'vbd-088-a1',
  titel:'Ongebruikt bouwdepot: aflossen of laten staan?',
  body:`Bij een klant blijft na de verbouwing een deel van het bouwdepot over. Moet dat worden afgelost of kan het worden gebruikt voor andere doelen?`,
  antwoorden:[
   {id:'vbd-088-a1',auteur:'u4',datum:'2026-08-17T21:39:00',rA:{u6:5},rAdv:{u6:5},body:`Een restant van het bouwdepot wordt meestal afgeboekt op de lening, vaak boetevrij. Gebruik voor andere doelen is vaak niet toegestaan, en fiscaal zou het niet aftrekbaar zijn als het niet aan de eigen woning wordt besteed. Controleer de voorwaarden van de geldverstrekker. Leg de afboeking vast in het dossier.`},
   {id:'vbd-088-a2',auteur:'u5',datum:'2026-08-18T14:43:00',rA:{u7:4},rAdv:{},body:`Fiscaal is het van belang om het niet-bestede deel ook in de aangifte goed te verwerken. Vraag een eindoverzicht van het depot op. Bewaar dat bij de facturen in het dossier.`}
  ]},
 {id:'vbd-089',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-21T08:10:00',views:180,tags:['NHG','verhuisregeling','meenemen'],beste:null,
  titel:'Verhuisregeling met NHG naar een duurdere woning',
  body:`Een klant heeft NHG en verhuist naar een woning boven de kostengrens. Kan hij de rente meenemen en wat gebeurt er met de NHG?`,
  antwoorden:[
   {id:'vbd-089-a1',auteur:'u5',datum:'2026-08-21T21:18:00',rA:{u2:4,u7:3,u3:4},rAdv:{u2:4,u3:4},body:`De rente kan vaak worden meegenomen, maar de NHG kan niet blijven bestaan als de nieuwe financiering niet aan de NHG-voorwaarden voldoet. Sommige geldverstrekkers rekenen dan een andere rente, omdat de NHG-korting vervalt. Raadpleeg de actuele NHG-voorwaarden en de voorwaarden van de geldverstrekker. Leg de gevolgen voor de rente vast in het dossier.`}
  ]},
 {id:'vbd-090',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-24T20:45:00',views:390,tags:['rente','looptijd','ouderen'],beste:'vbd-090-a1',
  titel:'Rentevaste periode voor een klant op hoge leeftijd',
  body:`Een oudere klant wil zijn hypotheek oversluiten en vraagt naar een lange rentevaste periode. Zijn er beperkingen vanwege de leeftijd?`,
  antwoorden:[
   {id:'vbd-090-a1',auteur:'u7',datum:'2026-08-25T10:10:00',rA:{u2:3},rAdv:{u2:3},body:`Er is geen algemene leeftijdsgrens, maar geldverstrekkers toetsen op het huidige en toekomstige inkomen. Sommige geldverstrekkers hebben speciale producten voor ouderen. Bespreek ook de gevolgen voor erfgenamen bij overlijden. Leg de toetsing en de afwegingen vast in het dossier.`},
   {id:'vbd-090-a2',auteur:'u2',datum:'2026-08-25T21:06:00',rA:{},rAdv:{},body:`Ik bespreek ook de vermogenssituatie en of aflossen uit vermogen een optie is. Soms is een kortere periode beter als er een verkoop of verhuizing aan zit te komen. Die afweging leg ik vast.`}
  ]},
 {id:'vbd-091',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-08-28T22:20:00',views:549,tags:['oversluiten','taxatie','modelmatige waardering'],beste:'vbd-091-a1',
  titel:'Modelmatige waardering voldoende voor lagere risicoklasse?',
  body:`Een klant wil een lagere risico-opslag op basis van een modelmatige waardering. Accepteren geldverstrekkers dat?`,
  antwoorden:[
   {id:'vbd-091-a1',auteur:'u4',datum:'2026-08-29T12:50:00',rA:{u6:5,u2:4},rAdv:{},body:`Een aantal geldverstrekkers accepteert een modelmatige waardering onder voorwaarden, bijvoorbeeld bij een lage verhouding lening tot waarde. Anderen vragen een volledige taxatie. Controleer de voorwaarden van de geldverstrekker. Leg de gebruikte waardebepaling en de uitkomst vast in het dossier.`}
  ]},
 {id:'vbd-092',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-01T11:00:00',views:256,tags:['rente','spaarrekening','depot'],beste:null,
  titel:'Hypotheek met een verbonden spaarrekening: renteberekening',
  body:`Bij een product met een gekoppelde spaarrekening krijgt de klant rente op het spaarsaldo gelijk aan de hypotheekrente. Hoe werkt dat bij renteherziening?`,
  antwoorden:[
   {id:'vbd-092-a1',auteur:'u1',datum:'2026-09-02T09:02:00',rA:{u6:4,u2:5,u5:3},rAdv:{},body:`Bij een gekoppelde spaarrekening volgt de spaarrente doorgaans de hypotheekrente, ook bij renteherziening. Een lagere hypotheekrente betekent dus ook een lagere spaarrente, waardoor er mogelijk meer moet worden ingelegd om het doelkapitaal te halen. Controleer de voorwaarden. Leg de gevolgen voor de inleg vast in het dossier.`},
   {id:'vbd-092-a2',auteur:'u3',datum:'2026-09-02T15:14:00',rA:{u2:4,u5:4},rAdv:{u5:4},body:`Vraag bij renteherziening altijd een nieuw inlegoverzicht op. Anders ontstaat er ongemerkt een tekort op de einddatum. Dat overzicht hoort in het dossier.`}
  ]},
 {id:'vbd-093',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-04T23:20:00',views:127,tags:['oversluiten','rente','second opinion'],beste:'vbd-093-a1',
  titel:'Klant komt met een rentevoorstel van een andere adviseur',
  body:`Een klant vraagt mij om een second opinion op een oversluitadvies van een andere adviseur. Hoe pakken jullie zo'n opdracht aan?`,
  antwoorden:[
   {id:'vbd-093-a1',auteur:'u8',datum:'2026-09-05T03:38:00',rA:{u3:5},rAdv:{},body:`Maak duidelijke afspraken over de opdracht en de vergoeding, en leg die schriftelijk vast. Beoordeel het advies op uitgangspunten, berekeningen en passendheid. Vermijd oordelen over de collega, focus op de inhoud. Leg je bevindingen en de reikwijdte van de opdracht vast in het dossier.`},
   {id:'vbd-093-a2',auteur:'u4',datum:'2026-09-05T07:43:00',rA:{u5:4},rAdv:{u5:4},body:`Ik reken altijd zelf de vergoeding en de break-evenperiode na. Daar zit vaak het verschil in uitkomsten. Bespreek de verschillen open met de klant.`}
  ]},
 {id:'vbd-094',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-08T09:20:00',views:546,tags:['rente','groene hypotheek','energiebesparing'],beste:null,
  titel:'Groen leningdeel voor verduurzaming: rente en voorwaarden',
  body:`Een klant wil verduurzamen en vraagt naar een groen leningdeel met rentekorting. Waar moet ik op letten?`,
  antwoorden:[
   {id:'vbd-094-a1',auteur:'u5',datum:'2026-09-08T20:20:00',rA:{u1:4,u4:4,u2:4},rAdv:{u1:4,u4:4},body:`Aandachtspunten bij een groen leningdeel:
- Voorwaarden voor de korting: vaak gekoppeld aan het energielabel na de verbouwing of aan specifieke maatregelen. Controleer welke maatregelen geaccepteerd worden en welke bewijsstukken nodig zijn.
- Bouwdepot: het geld komt meestal in een depot, met een termijn om de maatregelen uit te voeren. Wat als de termijn verloopt?
- Maximum: er kan een maximum zijn voor het groene deel.
- Korting: de rentekorting geldt soms alleen voor een bepaalde periode of alleen voor het groene deel.
- Alternatieven: een lening van het Warmtefonds of subsidie kan voordeliger zijn.
- Leenruimte: de extra leenruimte voor energiebesparende maatregelen (zie leennormen-2026.html).
In het dossier leg ik vast welke maatregelen zijn gepland, welke voorwaarden gelden en welke alternatieven zijn vergeleken.`}
  ]},
 {id:'vbd-095',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-12T08:00:00',views:562,tags:['rentevast','inkomen','zzp'],beste:'vbd-095-a1',
  titel:'Rentevaste periode voor een zzper met wisselend inkomen',
  body:`Een zzper met wisselend inkomen twijfelt over de rentevaste periode. Hoe nemen jullie de inkomensonzekerheid mee in de keuze?`,
  antwoorden:[
   {id:'vbd-095-a1',auteur:'u2',datum:'2026-09-12T12:46:00',rA:{},rAdv:{},body:`Bij een wisselend inkomen weegt de zekerheid van vaste lasten vaak zwaar. Ik reken scenario's met een tegenvallend jaar en een hogere rente bij herziening. Ook een buffer is belangrijk. Leg de scenario's en de keuze vast in het dossier.`},
   {id:'vbd-095-a2',auteur:'u3',datum:'2026-09-13T01:50:00',rA:{u6:5,u7:5},rAdv:{u6:5},body:`Bespreek in hetzelfde gesprek ook arbeidsongeschiktheid. Een hogere rente gecombineerd met inkomensverlies is het grootste risico. Leg vast welke keuze de klant daarin maakt.`}
  ]},
 {id:'vbd-096',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-15T23:40:00',views:569,tags:['rente','bereidstellingsprovisie','nieuwbouw'],beste:'vbd-096-a1',
  titel:'Bereidstellingsprovisie bij nieuwbouw: wanneer betaal je die?',
  body:`Bij een nieuwbouwproject wordt een bereidstellingsprovisie in rekening gebracht. Wanneer moet de klant die betalen en kan dat worden voorkomen?`,
  antwoorden:[
   {id:'vbd-096-a1',auteur:'u4',datum:'2026-09-16T12:36:00',rA:{u1:4},rAdv:{},body:`Bereidstellingsprovisie wordt vaak berekend over het deel dat na een bepaalde periode na de offertedatum nog niet is opgenomen. Bij sommige geldverstrekkers is het verrekenbaar of vervalt het bij passeren binnen een termijn. Controleer de voorwaarden. Leg de mogelijke kosten en de planning vast in het dossier.`}
  ]},
 {id:'vbd-097',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-19T10:00:00',views:184,tags:['rente','looptijd','tweede woning'],beste:null,
  titel:'Rente voor een tweede woning: andere voorwaarden?',
  body:`Een klant wil een tweede woning kopen voor eigen gebruik in het weekend. Gelden er andere rentes of voorwaarden?`,
  antwoorden:[
   {id:'vbd-097-a1',auteur:'u1',datum:'2026-09-19T13:26:00',rA:{u5:5},rAdv:{},body:`Een tweede woning valt fiscaal niet onder de eigen woning en de rente is dus niet aftrekbaar. Veel geldverstrekkers hebben aparte voorwaarden of rentes voor tweede woningen. Controleer de voorwaarden. Leg de fiscale positie en de toets vast in het dossier.`},
   {id:'vbd-097-a2',auteur:'u5',datum:'2026-09-20T13:40:00',rA:{u6:4},rAdv:{},body:`Fiscaal valt de tweede woning in box 3. Bespreek dat met de klant in netto lasten. Leg de berekening vast.`}
  ]},
 {id:'vbd-098',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-23T12:40:00',views:211,tags:['oversluiten','rente','terugverdientijd'],beste:'vbd-098-a1',
  titel:'Terugverdientijd van oversluiten berekenen',
  body:`Hoe berekenen jullie de terugverdientijd bij oversluiten? Gebruiken jullie bruto of netto bedragen?`,
  antwoorden:[
   {id:'vbd-098-a1',auteur:'u2',datum:'2026-09-23T18:02:00',rA:{u5:5},rAdv:{},body:`Ik gebruik netto bedragen, dus na fiscale effecten, omdat dat de werkelijke besparing voor de klant laat zien. Ik deel de totale kosten door de maandelijkse netto besparing. Ik vermeld daarbij de aannames over de rente na de rentevaste periode. Leg de berekening vast in het dossier.`},
   {id:'vbd-098-a2',auteur:'u4',datum:'2026-09-24T01:07:00',rA:{u2:5,u7:4},rAdv:{u2:5},body:`Ik laat ook een bruto variant zien, omdat fiscale regels kunnen wijzigen. Zo heeft de klant beide beelden. Noteer welke variant leidend was voor de keuze.`}
  ]},
 {id:'vbd-099',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-27T09:25:00',views:29,tags:['verhuisregeling','rente','tijdelijk dubbele lasten'],beste:null,
  titel:'Verhuisregeling en overbrugging: twee hypotheken tegelijk',
  body:`Een klant koopt een nieuwe woning voordat de oude is verkocht. Kan hij de rente meenemen terwijl de oude hypotheek nog loopt?`,
  antwoorden:[
   {id:'vbd-099-a1',auteur:'u4',datum:'2026-09-27T19:25:00',rA:{u1:4,u5:5,u2:3},rAdv:{u1:4,u5:5},body:`Vaak wel, maar het verschilt per geldverstrekker. De verhuisregeling gaat meestal pas in als de oude hypotheek is afgelost. Bij een overbrugging loopt de oude hypotheek nog door. Sommige geldverstrekkers laten de rente van de oude hypotheek direct meenemen naar de nieuwe, waarbij de oude hypotheek voor een tijd blijft bestaan naast de nieuwe; andere geldverstrekkers stellen als voorwaarde dat de oude woning verkocht is. Controleer de voorwaarden.
Let op:
- De verhuisregeling geldt vaak alleen bij dezelfde geldverstrekker.
- Het deel van de nieuwe hypotheek boven de meegenomen hypotheek krijgt de actuele rente.
- De toetsing gebeurt op de dubbele lasten, tenzij de oude woning onvoorwaardelijk verkocht is.
Gebruik overbrugging.html om de dubbele lasten en de overbrugging te berekenen.
In het dossier leg ik vast hoe de rente wordt meegenomen, welke termijnen gelden en hoe de dubbele lasten zijn getoetst.`}
  ]},
 {id:'vbd-100',cat:'hyp',auteur:null,naam:'',voorbeeld:true,datum:'2026-09-26T18:00:00',views:147,tags:['rente','aflosvorm','kinderen'],beste:'vbd-100-a1',
  titel:'Aflosvorm afstemmen op de gezinssituatie',
  body:`Een jong gezin vraagt naar een aflosvorm die past bij hogere kosten voor kinderen in de komende jaren. Hoe adviseren jullie hierover?`,
  antwoorden:[
   {id:'vbd-100-a1',auteur:'u2',datum:'2026-09-27T11:00:00',rA:{u7:4,u5:5},rAdv:{u7:4,u5:5},body:`Ik breng de verwachte kosten in kaart en vergelijk annuitair en lineair op de lasten in de komende jaren. Annuitair geeft vaak meer ruimte in de beginjaren. Een buffer voor onverwachte kosten is belangrijk. Leg de afweging en de keuze vast in het dossier.`},
   {id:'vbd-100-a2',auteur:'u1',datum:'2026-09-28T01:12:00',rA:{u8:3,u5:5},rAdv:{},body:`Ik bespreek ook de mogelijkheid van extra aflossen later, als de kosten weer dalen. Zo blijft er flexibiliteit. Controleer wel de boetevrije ruimte in de voorwaarden van de geldverstrekker.`}
  ]}
]);
